changeSet.sql:
SET LOCAL lock_timeout='30s';
SET LOCAL statement_timeout='0';
DO $$
DECLARE guard_mode "char"; source_check text; target_check text; source_scope text; target_scope text;
BEGIN
 LOCK TABLE config_audit_event IN ACCESS EXCLUSIVE MODE;
 SELECT tgenabled INTO guard_mode FROM pg_trigger
 WHERE tgrelid='config_audit_event'::regclass AND tgname='trg_config_audit_event_block_mutation' AND NOT tgisinternal;
 SELECT pg_get_constraintdef(oid) INTO source_check FROM pg_constraint
 WHERE conrelid='config_audit_event'::regclass AND conname='ck_config_audit_event_entity_type' AND contype='c' AND convalidated;
 IF source_check IS NULL THEN RAISE EXCEPTION 'released audit entity-type constraint is missing or unvalidated'; END IF;
 target_check:=replace(replace(replace(replace(source_check,'''REVIEW_BACKFILL_RUN''','''REVIEW_BATCH'''),'''REVIEW_SWEEP_SCHEDULE''','''REVIEW_SCHEDULE'''),'''CURATED_PRACTICE''','''CATALOG_PRACTICE'''),'''CURATED_PRACTICE_GROUP''','''CATALOG_GROUP''');
 target_check:=replace(replace(target_check,'''CURATED_PRACTICE_AREA''','''CATALOG_GROUP'''),'''PRACTICE_AREA''','''PRACTICE_GROUP''');
 SELECT pg_get_constraintdef(oid) INTO source_scope FROM pg_constraint
 WHERE conrelid='config_audit_event'::regclass AND conname='ck_config_audit_event_scope' AND contype='c' AND convalidated;
 IF source_scope IS NULL THEN RAISE EXCEPTION 'released audit scope constraint is missing or unvalidated'; END IF;
 target_scope:=replace(replace(source_scope,'''CURATED_PRACTICE''','''CATALOG_PRACTICE'''),'''CURATED_PRACTICE_AREA''','''CATALOG_GROUP''');
 target_scope:='CHECK ('||substring(target_scope FROM 7)||' OR entity_type=''CATALOG_GROUP'')';
 IF guard_mode IN('O','R','A') THEN ALTER TABLE config_audit_event DISABLE TRIGGER trg_config_audit_event_block_mutation; END IF;
 IF target_check IS DISTINCT FROM source_check THEN
  ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_entity_type;
  EXECUTE 'ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type '||target_check||' NOT VALID';
 END IF;
 ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_scope;
 EXECUTE 'ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_scope '||target_scope||' NOT VALID';
 UPDATE config_audit_event SET entity_type=CASE entity_type
  WHEN 'REVIEW_BACKFILL_RUN' THEN 'REVIEW_BATCH' WHEN 'REVIEW_SWEEP_SCHEDULE' THEN 'REVIEW_SCHEDULE'
  WHEN 'CURATED_PRACTICE' THEN 'CATALOG_PRACTICE' WHEN 'CURATED_PRACTICE_GROUP' THEN 'CATALOG_GROUP'
  WHEN 'CURATED_PRACTICE_AREA' THEN 'CATALOG_GROUP' WHEN 'PRACTICE_AREA' THEN 'PRACTICE_GROUP' END
 WHERE entity_type IN('REVIEW_BACKFILL_RUN','REVIEW_SWEEP_SCHEDULE','CURATED_PRACTICE','CURATED_PRACTICE_GROUP','CURATED_PRACTICE_AREA','PRACTICE_AREA');
 ALTER TABLE config_audit_event VALIDATE CONSTRAINT ck_config_audit_event_entity_type;
 ALTER TABLE config_audit_event VALIDATE CONSTRAINT ck_config_audit_event_scope;
 CASE guard_mode
  WHEN 'O' THEN ALTER TABLE config_audit_event ENABLE TRIGGER trg_config_audit_event_block_mutation;
  WHEN 'R' THEN ALTER TABLE config_audit_event ENABLE REPLICA TRIGGER trg_config_audit_event_block_mutation;
  WHEN 'A' THEN ALTER TABLE config_audit_event ENABLE ALWAYS TRIGGER trg_config_audit_event_block_mutation;
  ELSE NULL;
 END CASE;
END $$;

CREATE TEMP TABLE _cutover_clock ON COMMIT DROP AS SELECT transaction_timestamp() AS at;
CREATE FUNCTION pg_temp.cutover_array(v jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
 IF v IS NULL OR v='null'::jsonb THEN RETURN '[]'::jsonb; END IF;
 IF jsonb_typeof(v)<>'array' THEN RAISE EXCEPTION 'released array has an unrepresentable shape'; END IF;
 RETURN v;
END $$;

CREATE TEMP TABLE _cutover_sequence(table_name text PRIMARY KEY,last_value bigint NOT NULL,is_called boolean NOT NULL) ON COMMIT DROP;
CREATE FUNCTION pg_temp.cutover_align_sequence(target text,source_name text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE seq text; current_value bigint; called boolean; row_max bigint; prior _cutover_sequence%ROWTYPE;
BEGIN
 seq:=pg_get_serial_sequence(target,'id');
 EXECUTE format('SELECT last_value,is_called FROM %s',seq) INTO current_value,called;
 EXECUTE format('SELECT max(id) FROM %I',target) INTO row_max;
 IF source_name IS NOT NULL THEN SELECT * INTO prior FROM _cutover_sequence WHERE table_name=source_name; END IF;
 PERFORM setval(seq,GREATEST(current_value,COALESCE(row_max,current_value),COALESCE(prior.last_value,current_value)),
  called OR COALESCE(prior.is_called,false) OR row_max IS NOT NULL);
END $$;

LOCK TABLE identity_link,person_suppression,public_activity_objection,workspace_membership,workspace_hidden_former_member,workspace_member_onboarding,practice_review_person_target,user_preferences,account_ai_choice,practice,practice_revision,practice_group,curated_practice_override,curated_group_override,practice_catalog_installation,practice_review_repository_target,review_sweep_schedule,review_backfill_run,artifact_signal,agent_job,observation,observation_invalidation,feedback,feedback_observation,feedback_placement,feedback_dispatch,feedback_approval,feedback_withdrawal,reaction,delivery_policy_evaluation,public_review_completion,review_composition_basis,account,auth_event,chat_thread,chat_message,chat_message_vote,slack_message,slack_thread,slack_channel_consent_event,sync_job,llm_usage_event IN ACCESS EXCLUSIVE MODE;
CREATE TEMP TABLE _cutover_old_identity_link ON COMMIT DROP AS TABLE identity_link;
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT conname FROM pg_constraint WHERE conrelid='identity_link'::regclass AND contype IN ('p','u','x') LOOP
  EXECUTE format('ALTER TABLE identity_link RENAME CONSTRAINT %I TO %I',r.conname,'_released_'||substr(r.conname,1,53));
 END LOOP;
 FOR r IN SELECT indexrelid::regclass::text AS name FROM pg_index WHERE indrelid='identity_link'::regclass
  AND indexrelid NOT IN (SELECT conindid FROM pg_constraint WHERE conrelid='identity_link'::regclass) LOOP
  EXECUTE format('ALTER INDEX %s RENAME TO %I',r.name,'_released_'||substr(r.name,1,53));
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='identity_link'::regclass AND attname='id' AND NOT attisdropped) THEN
 IF pg_get_serial_sequence('identity_link','id') IS NOT NULL THEN
  EXECUTE format('INSERT INTO _cutover_sequence SELECT %L,last_value,is_called FROM %s','identity_link',pg_get_serial_sequence('identity_link','id'));
  EXECUTE format('ALTER SEQUENCE %s RENAME TO %I',pg_get_serial_sequence('identity_link','id'),'_released_identity_link_id_seq');
 END IF;
 END IF;
END $$;
ALTER TABLE identity_link RENAME TO _released_identity_link;
