-- The released message tenant is its thread tenant. Create the target key before copy FKs.
ALTER TABLE chat_message ADD COLUMN workspace_id bigint;
UPDATE chat_message m SET workspace_id=t.workspace_id FROM chat_thread t WHERE t.id=m.thread_id;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM chat_message WHERE workspace_id IS NULL)
 OR EXISTS(SELECT 1 FROM chat_message m JOIN chat_message p ON p.id=m.parent_message_id WHERE m.workspace_id<>p.workspace_id) THEN
  RAISE EXCEPTION 'chat message tenant or parent is inconsistent'; END IF;
END $$;
ALTER TABLE chat_message ALTER COLUMN workspace_id SET NOT NULL;
ALTER TABLE chat_message ADD CONSTRAINT uk_chat_message_tenant UNIQUE(id,workspace_id);

ALTER TABLE account DROP CONSTRAINT ck_account_status;
ALTER TABLE account ADD COLUMN ai_choice varchar(24), ADD COLUMN ai_choice_at timestamptz,
 ADD COLUMN feedback_delivery_enabled boolean NOT NULL DEFAULT true;
ALTER TABLE account ADD CONSTRAINT ck_account_status CHECK(status IN ('UNCLAIMED','ACTIVE','SUSPENDED','DELETING','DELETED'));
ALTER TABLE account ADD CONSTRAINT ck_account_unclaimed CHECK(status<>'UNCLAIMED' OR (primary_email IS NULL AND primary_email_verified_at IS NULL AND app_role='USER'));
ALTER TABLE account ADD CONSTRAINT ck_account_ai_choice CHECK(ai_choice IS NULL OR ai_choice IN ('NO_AI','IN_HOUSE_ONLY','CLOUD'));
ALTER TABLE account ADD CONSTRAINT ck_account_ai_choice_time CHECK((ai_choice IS NULL)=(ai_choice_at IS NULL));
CREATE FUNCTION review_model_digest(models jsonb) RETURNS varchar(64)
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
 SELECT encode(sha256(convert_to(COALESCE(jsonb_agg(value ORDER BY value->>'slot'),'[]'::jsonb)::text,'UTF8')),'hex')::varchar(64)
 FROM jsonb_array_elements(models)
$$;
CREATE FUNCTION practice_review_digest(d jsonb) RETURNS varchar(96)
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
 SELECT ('v6:' || encode(sha256(convert_to(jsonb_build_object(
  'knownFields',jsonb_build_object('appliesWhen',d ? 'appliesWhen','about',d ? 'about',
    'reads',d ? 'reads','reviewedBy',d ? 'reviewedBy','criteria',d ? 'criteria','script',d ? 'script','scan',d ? 'scan'),
  'appliesWhen',d->'appliesWhen','about',d->'about','reads',d->'reads',
  'reviewedBy',d->'reviewedBy','criteria',d->'criteria','script',d->'script','scan',d->'scan'
 )::text,'UTF8')),'hex'))::varchar(96)
$$;

CREATE TABLE identity (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id bigint NOT NULL,
  provider_id bigint NOT NULL,
  provider_user_key varchar(255) NOT NULL,
  team_key varchar(255) NOT NULL DEFAULT '',
  linked_via varchar(16) NOT NULL,
  linked_at timestamptz NOT NULL DEFAULT now(),
  last_login_at timestamptz,
  disabled_at timestamptz,
  CONSTRAINT sfk_identity_account FOREIGN KEY(account_id) REFERENCES account(id) ON DELETE CASCADE,
  CONSTRAINT sfk_identity_provider FOREIGN KEY(provider_id) REFERENCES identity_provider(id) ON DELETE RESTRICT,
  CONSTRAINT ck_identity_key CHECK(btrim(provider_user_key) <> ''),
  CONSTRAINT ck_identity_linked_via CHECK(linked_via IN ('ROSTER','SIGN_IN','MANUAL'))
);


CREATE TABLE identity_restriction (
  id uuid PRIMARY KEY,
  provider_id bigint NOT NULL,
  provider_user_key varchar(255) NOT NULL,
  team_key varchar(255) NOT NULL DEFAULT '',
  kind varchar(16) NOT NULL,
  active_request_id uuid,
  CONSTRAINT uk_identity_restriction_key UNIQUE(provider_id, provider_user_key, team_key, kind),
  CONSTRAINT ck_identity_restriction_kind CHECK(kind IN ('ERASED','HIDE_PUBLIC')),
  CONSTRAINT ck_identity_restriction_request CHECK(kind = 'ERASED' OR active_request_id IS NULL),
  CONSTRAINT sfk_identity_restriction_provider FOREIGN KEY(provider_id) REFERENCES identity_provider(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_identity_restriction_request FOREIGN KEY(active_request_id) REFERENCES person_data_request(id) ON DELETE SET NULL
);


CREATE TABLE membership (
  workspace_id bigint NOT NULL,
  account_id bigint NOT NULL,
  role varchar(16) NOT NULL DEFAULT 'MEMBER',
  hidden boolean NOT NULL DEFAULT false,
  review_selected boolean NOT NULL DEFAULT false,
  onboarding_seen_revision bigint,
  public_activity_seen boolean NOT NULL DEFAULT false,
  joined_at timestamptz NOT NULL DEFAULT now(),
  left_at timestamptz,
  PRIMARY KEY(account_id, workspace_id),
  CONSTRAINT sfk_membership_account FOREIGN KEY(account_id) REFERENCES account(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_membership_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT ck_membership_role CHECK(role IN ('OWNER','ADMIN','MEMBER')),
  CONSTRAINT ck_membership_dates CHECK(left_at IS NULL OR left_at >= joined_at),
  CONSTRAINT ck_membership_seen_revision CHECK(onboarding_seen_revision IS NULL OR onboarding_seen_revision >= 0)
);


CREATE TABLE item (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workspace_id bigint NOT NULL,
  kind varchar(64) NOT NULL,
  parent_id bigint,
  source_id bigint,
  path text,
  created_at timestamptz NOT NULL DEFAULT now(),
  removed_at timestamptz,
  CONSTRAINT uk_item_workspace UNIQUE(id, workspace_id),
  CONSTRAINT sfk_item_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_item_parent FOREIGN KEY(parent_id, workspace_id) REFERENCES item(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT ck_item_kind CHECK(kind ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$'),
  CONSTRAINT ck_item_source CHECK((path IS NULL) <> (source_id IS NULL)),
  CONSTRAINT ck_item_parent CHECK(parent_id IS DISTINCT FROM id),
  CONSTRAINT ck_item_positive_source CHECK(source_id IS NULL OR source_id > 0),
  CONSTRAINT ck_item_path CHECK(path IS NULL OR (btrim(path) <> '' AND parent_id IS NOT NULL))
);


CREATE TABLE item_event (
  id uuid PRIMARY KEY,
  workspace_id bigint NOT NULL,
  item_id bigint NOT NULL,
  name varchar(128) NOT NULL,
  item_version text NOT NULL,
  occurred_at timestamptz NOT NULL,
  found_by varchar(16) NOT NULL,
  actor_user_id bigint,
  requested_by_id bigint,
  state varchar(16) NOT NULL DEFAULT 'RECORDED',
  reason varchar(48),
  decided_at timestamptz NOT NULL,
  last_attempted_at timestamptz,
  retry_at timestamptz,
  CONSTRAINT uk_item_event_workspace UNIQUE(id, workspace_id),
  CONSTRAINT uk_item_event_key UNIQUE(workspace_id, item_id, name, item_version),
  CONSTRAINT sfk_item_event_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_item_event_item FOREIGN KEY(item_id, workspace_id) REFERENCES item(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_item_event_actor FOREIGN KEY(actor_user_id) REFERENCES "user"(id) ON DELETE SET NULL,
  CONSTRAINT sfk_item_event_requester FOREIGN KEY(requested_by_id) REFERENCES account(id) ON DELETE SET NULL,
  CONSTRAINT ck_item_event_found_by CHECK(found_by IN ('WEBHOOK','SYNC','REQUEST','BACKFILL','SCHEDULE')),
  CONSTRAINT ck_item_event_state CHECK(state IN ('RECORDED','WAITING','STARTED','WITHHELD','BLOCKED','EXPIRED')),
  CONSTRAINT ck_item_event_name CHECK(name ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$'),
  CONSTRAINT ck_item_event_version CHECK(btrim(item_version) <> ''),
 CONSTRAINT ck_item_event_reason CHECK(reason IS NULL OR reason IN ('GATE_WITHHELD','COOLDOWN_ACTIVE','REQUEST_COOLDOWN_ACTIVE','REQUESTER_QUOTA_EXHAUSTED','CONCURRENT_DUPLICATE','COALESCED','OUT_OF_REVIEW_SCOPE','BOT_AUTHOR','BOT_REVIEWER','STALE_ROLLOUT_REVISION','WORKSPACE_INACTIVE','PRACTICES_DISABLED','NO_ACTIVE_PRACTICE','REVIEW_MODEL_UNBOUND','MEMBER_AI_DECLINED','PERSON_DATA_ERASED','FEEDBACK_MODE_OFF','SUBJECT_UNLINKED','MERGE_ACTOR_UNAVAILABLE','MODEL_UNAVAILABLE','BUDGET_EXHAUSTED','ITEM_NOT_VISIBLE','PENDING_DEADLINE_EXCEEDED','ITEM_GONE','VERSION_SUPERSEDED'))
);


CREATE TABLE practice_group (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workspace_id bigint NOT NULL,
  slug varchar(64) NOT NULL,
  name varchar(128) NOT NULL,
  description text,
  icon varchar(64), color varchar(32),
  position integer NOT NULL DEFAULT 0,
  shown_to_developers boolean NOT NULL DEFAULT true,
  feedback_mode varchar(16),
  catalog_slug varchar(64), catalog_base jsonb,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz,
  CONSTRAINT uk_practice_group_workspace_id UNIQUE (id, workspace_id),
  CONSTRAINT uk_practice_group_workspace_slug UNIQUE (workspace_id, slug),
  CONSTRAINT fk_practice_group_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT ck_practice_group_position CHECK (position >= 0),
  CONSTRAINT ck_practice_group_feedback_mode CHECK (feedback_mode IS NULL OR feedback_mode IN ('OFF','APPROVE_FIRST','AUTOMATIC')),
  CONSTRAINT ck_practice_group_catalog CHECK ((catalog_slug IS NULL) = (catalog_base IS NULL)),
  CONSTRAINT ck_practice_group_catalog_base CHECK (catalog_base IS NULL OR jsonb_typeof(catalog_base) = 'object')
);


CREATE TABLE practice (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workspace_id bigint NOT NULL,
  slug varchar(64) NOT NULL, kind varchar(64) NOT NULL,
  group_id bigint,
  position integer NOT NULL DEFAULT 0,
  current_version_id bigint NOT NULL,
  feedback_mode varchar(16),
  catalog_slug varchar(64), catalog_base jsonb,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz,
  CONSTRAINT uk_practice_workspace_id UNIQUE (id, workspace_id),
  CONSTRAINT uk_practice_workspace_slug UNIQUE (workspace_id, slug),
  CONSTRAINT fk_practice_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_practice_group FOREIGN KEY (group_id, workspace_id)
    REFERENCES practice_group(id, workspace_id) ON DELETE SET NULL (group_id),
  CONSTRAINT ck_practice_kind CHECK (kind ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$'),
  CONSTRAINT ck_practice_position CHECK (position >= 0),
  CONSTRAINT ck_practice_feedback_mode CHECK (feedback_mode IS NULL OR feedback_mode IN ('OFF','APPROVE_FIRST','AUTOMATIC')),
  CONSTRAINT ck_practice_catalog CHECK ((catalog_slug IS NULL) = (catalog_base IS NULL)),
  CONSTRAINT ck_practice_catalog_base CHECK (catalog_base IS NULL OR jsonb_typeof(catalog_base) = 'object')
);


CREATE TABLE practice_version (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workspace_id bigint NOT NULL,
  practice_id bigint NOT NULL,
  number integer NOT NULL,
  definition jsonb NOT NULL,
  name varchar(128) GENERATED ALWAYS AS ((definition ->> 'name')::varchar(128)) STORED,
  review_digest varchar(96) GENERATED ALWAYS AS (practice_review_digest(definition)) STORED NOT NULL,
  created_by_account_id bigint,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_practice_version_workspace_id UNIQUE (id, workspace_id),
  CONSTRAINT uk_practice_version_owner UNIQUE (id, practice_id, workspace_id),
  CONSTRAINT uk_practice_version_number UNIQUE (practice_id, number),
  CONSTRAINT sfk_practice_version_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_practice_version_practice FOREIGN KEY (practice_id, workspace_id)
    REFERENCES practice(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT sfk_practice_version_creator FOREIGN KEY (created_by_account_id) REFERENCES account(id) ON DELETE SET NULL,
  CONSTRAINT ck_practice_version_number CHECK (number >= 1),
  CONSTRAINT ck_practice_version_definition CHECK (jsonb_typeof(definition) = 'object' AND jsonb_exists(definition, 'criteria')),
  CONSTRAINT ck_practice_version_digest CHECK (review_digest ~ '^v6:[0-9a-f]{64}$')
);


CREATE TABLE catalog_entry (
  entry_type varchar(16) NOT NULL,
  slug varchar(64) NOT NULL,
  kind varchar(64),
  definition jsonb,
  base jsonb,
  position integer,
  excluded_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  version bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (entry_type, slug),
  CONSTRAINT ck_catalog_entry_type CHECK (entry_type IN ('PRACTICE','GROUP')),
  CONSTRAINT ck_catalog_entry_kind CHECK (((entry_type='GROUP' OR definition IS NULL)=(kind IS NULL)) AND
    (kind IS NULL OR kind ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$')),
  CONSTRAINT ck_catalog_entry_definition CHECK (definition IS NULL OR jsonb_typeof(definition) = 'object'),
  CONSTRAINT ck_catalog_entry_base CHECK (base IS NULL OR jsonb_typeof(base) = 'object'),
  CONSTRAINT ck_catalog_entry_position CHECK (position IS NULL OR position >= 0),
  CONSTRAINT ck_catalog_entry_version CHECK (version >= 0)
);


CREATE TABLE review_scope_repository (
  workspace_id bigint NOT NULL,
  repository_monitor_id bigint NOT NULL,
  base_branches jsonb NOT NULL DEFAULT '[]'::jsonb,
  PRIMARY KEY (repository_monitor_id, workspace_id),
  CONSTRAINT sfk_review_scope_repository_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_scope_repository_monitor FOREIGN KEY (repository_monitor_id, workspace_id)
    REFERENCES repository_to_monitor(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT ck_review_scope_repository_branches CHECK (
    jsonb_typeof(base_branches) = 'array' AND
    NOT jsonb_path_exists(base_branches, '$[*] ? (@.type() != "string" || @ like_regex "^[[:space:]]*$" || @ like_regex "^.{255}." flag "s")'))
);


CREATE TABLE review_schedule (
  id uuid PRIMARY KEY,
  version bigint NOT NULL DEFAULT 0,
  workspace_id bigint NOT NULL,
  kind varchar(64) NOT NULL,
  cadence varchar(16) NOT NULL DEFAULT 'DAILY',
  lookback_days integer,
  budget_usd numeric(18,6),
  enabled boolean NOT NULL DEFAULT true,
  next_run_at timestamptz NOT NULL,
  last_run_at timestamptz,
  created_by_account_id bigint,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_review_schedule_workspace_id UNIQUE (id, workspace_id),
  CONSTRAINT uk_review_schedule_workspace_kind UNIQUE (workspace_id, kind),
  CONSTRAINT sfk_review_schedule_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_schedule_creator FOREIGN KEY (created_by_account_id) REFERENCES account(id) ON DELETE SET NULL,
  CONSTRAINT ck_review_schedule_kind CHECK (kind ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$'),
  CONSTRAINT ck_review_schedule_cadence CHECK (cadence IN ('DAILY','WEEKLY')),
  CONSTRAINT ck_review_schedule_lookback CHECK ((kind='scm.repository' AND lookback_days IS NULL) OR
    (kind<>'scm.repository' AND lookback_days IS NOT NULL AND lookback_days BETWEEN 1 AND CASE cadence WHEN 'DAILY' THEN 2 WHEN 'WEEKLY' THEN 7 END)),
  CONSTRAINT ck_review_schedule_budget CHECK ((kind='scm.repository' AND budget_usd IS NOT NULL AND budget_usd BETWEEN 0.0001 AND 100000 AND round(budget_usd,4)=budget_usd) OR
    (kind<>'scm.repository' AND budget_usd IS NULL)),
  CONSTRAINT ck_review_schedule_version CHECK (version >= 0)
);


CREATE TABLE review_batch (
  id uuid PRIMARY KEY,
  version bigint NOT NULL DEFAULT 0,
  workspace_id bigint NOT NULL,
  kind varchar(64) NOT NULL,
  origin varchar(16) NOT NULL DEFAULT 'BACKFILL',
  schedule_id uuid,
  from_at timestamptz,
  to_at timestamptz,
  status varchar(24) NOT NULL DEFAULT 'AWAITING_CONFIRMATION',
  pause_reason varchar(32),
  budget_usd numeric(18,6),
  estimated_items integer NOT NULL DEFAULT 0,
  estimated_cost_usd numeric(12,4),
  cursor_item_id bigint,
  submitted_count integer NOT NULL DEFAULT 0,
  skipped_count integer NOT NULL DEFAULT 0,
  failed_count integer NOT NULL DEFAULT 0,
  requested_by_account_id bigint,
  confirmed_by_account_id bigint,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  started_at timestamptz, finished_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_review_batch_workspace_id UNIQUE (id, workspace_id),
  CONSTRAINT sfk_review_batch_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_batch_schedule FOREIGN KEY (schedule_id, workspace_id)
    REFERENCES review_schedule(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_batch_cursor FOREIGN KEY (cursor_item_id, workspace_id)
    REFERENCES item(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_batch_requester FOREIGN KEY (requested_by_account_id) REFERENCES account(id) ON DELETE SET NULL,
  CONSTRAINT sfk_review_batch_confirmer FOREIGN KEY (confirmed_by_account_id) REFERENCES account(id) ON DELETE SET NULL,
  CONSTRAINT ck_review_batch_budget CHECK((kind='scm.repository' AND budget_usd IS NOT NULL AND budget_usd BETWEEN 0.0001 AND 100000 AND round(budget_usd,4)=budget_usd) OR (kind<>'scm.repository' AND budget_usd IS NULL)),
  CONSTRAINT ck_review_batch_kind CHECK (kind ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$'),
  CONSTRAINT ck_review_batch_origin CHECK(origin IN ('BACKFILL','SCHEDULE')),
  CONSTRAINT ck_review_batch_origin_link CHECK(schedule_id IS NULL OR origin='SCHEDULE'),
  CONSTRAINT ck_review_batch_window CHECK ((kind='scm.repository' AND from_at IS NULL AND to_at IS NULL) OR
    (kind<>'scm.repository' AND from_at IS NOT NULL AND to_at IS NOT NULL AND from_at<to_at)),
  CONSTRAINT ck_review_batch_status CHECK (status IN ('AWAITING_CONFIRMATION','RUNNING','PAUSED','COMPLETED','CANCELLED')),
  CONSTRAINT ck_review_batch_pause CHECK ((status = 'PAUSED') = (pause_reason IS NOT NULL)),
  CONSTRAINT ck_review_batch_pause_reason CHECK (pause_reason IS NULL OR pause_reason IN ('BUDGET_EXHAUSTED','REVIEW_MODEL_UNBOUND','WORKSPACE_UNAVAILABLE','PAUSED_BY_ADMIN')),
  CONSTRAINT ck_review_batch_counts CHECK (estimated_items >= 0 AND submitted_count >= 0 AND skipped_count >= 0 AND failed_count >= 0),
  CONSTRAINT ck_review_batch_cost CHECK (estimated_cost_usd IS NULL OR estimated_cost_usd >= 0),
  CONSTRAINT ck_review_batch_version CHECK (version >= 0)
);


CREATE TABLE review_batch_target (
 batch_id uuid NOT NULL,item_id bigint NOT NULL,workspace_id bigint NOT NULL,
 PRIMARY KEY(batch_id,item_id),
 CONSTRAINT uk_review_batch_target_tenant UNIQUE(batch_id,item_id,workspace_id),
 CONSTRAINT sfk_review_batch_target_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
 CONSTRAINT sfk_review_batch_target_batch FOREIGN KEY(batch_id,workspace_id) REFERENCES review_batch(id,workspace_id) ON DELETE CASCADE,
 CONSTRAINT sfk_review_batch_target_item FOREIGN KEY(item_id,workspace_id) REFERENCES item(id,workspace_id) ON DELETE RESTRICT
);


CREATE TABLE review (
  id uuid PRIMARY KEY,
  workspace_id bigint NOT NULL,
  item_id bigint NOT NULL,
  kind varchar(8) NOT NULL DEFAULT 'ITEM',
  item_version text,
  base_version text,
  origin varchar(16) NOT NULL,
  event_id uuid,
  batch_id uuid,
  requested_by_id bigint,
  status varchar(16) NOT NULL DEFAULT 'QUEUED',
  stop_reason varchar(48),
  budget_usd numeric(18,6),
  rollout_revision bigint NOT NULL DEFAULT 0,
  ordered_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  admitted_at timestamptz,
  completed_at timestamptz,
  public_review_at timestamptz,
  report jsonb,
  inventory_receipt jsonb,
  request_key uuid,
  request_digest varchar(64),
  checks jsonb NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT uk_review_request UNIQUE(workspace_id,request_key),
  CONSTRAINT ck_review_request_pair CHECK((request_key IS NULL)=(request_digest IS NULL)),
  CONSTRAINT ck_review_request_digest CHECK(request_digest IS NULL OR request_digest ~ '^[0-9a-f]{64}$'),
  CONSTRAINT uk_review_workspace UNIQUE(id, workspace_id),
  CONSTRAINT sfk_review_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_item FOREIGN KEY(item_id, workspace_id) REFERENCES item(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_event FOREIGN KEY(event_id, workspace_id) REFERENCES item_event(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_batch FOREIGN KEY(batch_id, workspace_id) REFERENCES review_batch(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_requester FOREIGN KEY(requested_by_id) REFERENCES account(id) ON DELETE SET NULL,
  CONSTRAINT ck_review_kind CHECK(kind IN ('ITEM','SCAN')),
  CONSTRAINT ck_review_origin CHECK(origin IN ('EVENT','REQUEST','BACKFILL','SCHEDULE')),
  CONSTRAINT ck_review_origin_links CHECK((event_id IS NULL OR origin='EVENT')
    AND (batch_id IS NULL OR origin IN ('BACKFILL','SCHEDULE'))
    AND (requested_by_id IS NULL OR origin='REQUEST')),
  CONSTRAINT ck_review_status CHECK(status IN ('QUEUED','RUNNING','COMPLETE','PARTIAL','FAILED','CANCELLED')),
  CONSTRAINT ck_review_completed CHECK((status IN ('COMPLETE','PARTIAL','FAILED','CANCELLED')) = (completed_at IS NOT NULL)),
  CONSTRAINT ck_review_reason CHECK((status IN ('PARTIAL','FAILED','CANCELLED')) = (stop_reason IS NOT NULL)),
  CONSTRAINT ck_review_budget CHECK((budget_usd IS NULL OR (budget_usd BETWEEN 0.0001 AND 100000 AND round(budget_usd,4)=budget_usd)) AND
    (kind<>'SCAN' OR budget_usd IS NOT NULL)),
  CONSTRAINT ck_review_inventory CHECK(inventory_receipt IS NULL OR (kind='SCAN' AND jsonb_typeof(inventory_receipt)='object')),
  CONSTRAINT ck_review_checks CHECK(jsonb_typeof(checks)='object'),
  CONSTRAINT ck_review_report CHECK(report IS NULL OR (kind='SCAN' AND jsonb_typeof(report)='object')),
 CONSTRAINT ck_review_stop_reason CHECK(stop_reason IS NULL OR stop_reason IN ('TIMED_OUT','EXECUTION_FAILED','PREPARATION_FAILED','PROCESSING_FAILED','PERSON_DATA_ERASED','STALE_ROLLOUT_REVISION','CANCELLED_BY_ADMIN','REPLACED','LEGACY_FAILURE','EXECUTION_INCOMPLETE','RESULT_WITHHELD','READINESS_REFUSED','SUSPECT_LISTING','BUDGET','DEADLINE','CANCELLED','ENUMERATION_FAILED','ENUMERATION_LIMIT','NO_SCAN_PRACTICES','MODEL_CHANGED','MODEL_UNAVAILABLE','ERROR','LEGACY_SCOPE_UNKNOWN','CONTRACT_CHANGED'))
);


CREATE TABLE review_practice (
  review_id uuid NOT NULL,
  practice_id bigint NOT NULL,
  workspace_id bigint NOT NULL,
  practice_version_id bigint,
  status varchar(16) NOT NULL DEFAULT 'QUEUED',
  reason varchar(48),
  items_listed integer,
  listing_complete boolean,
  capture_decision jsonb,
  method jsonb,
  PRIMARY KEY(review_id, practice_id),
  CONSTRAINT uk_review_practice_tenant UNIQUE(review_id, practice_id, workspace_id),
  CONSTRAINT sfk_review_practice_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_practice_review FOREIGN KEY(review_id, workspace_id) REFERENCES review(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT sfk_review_practice_practice FOREIGN KEY(practice_id, workspace_id) REFERENCES practice(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_practice_version FOREIGN KEY(practice_version_id, practice_id, workspace_id)
    REFERENCES practice_version(id, practice_id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT ck_review_practice_status CHECK(status IN ('QUEUED','READY','RUNNING','DONE','WITHHELD','FAILED')),
  CONSTRAINT ck_review_practice_reason CHECK(status NOT IN ('WITHHELD','FAILED') OR reason IS NOT NULL),
  CONSTRAINT ck_review_practice_method CHECK(method IS NULL OR
    (jsonb_typeof(method)='object' AND jsonb_typeof(method->'models')='array'
     AND CASE WHEN jsonb_typeof(method->'models')='array' THEN
       COALESCE(method->>'modelDigest'=review_model_digest(method->'models'),false) ELSE false END
     AND method-'epoch'-'modelDigest'-'models'='{}'::jsonb
     AND CASE WHEN jsonb_typeof(method->'epoch')='number' THEN (method->>'epoch')::numeric>=1 AND (method->>'epoch')::numeric=trunc((method->>'epoch')::numeric) ELSE false END)),
  CONSTRAINT ck_review_practice_decision CHECK(capture_decision IS NULL OR jsonb_typeof(capture_decision)='object'),
  CONSTRAINT ck_review_practice_counts CHECK(items_listed IS NULL OR items_listed >= 0)
);


CREATE TABLE review_job (
  id uuid PRIMARY KEY,
  review_id uuid NOT NULL,
  workspace_id bigint NOT NULL,
  submitted_at timestamptz NOT NULL,
  status varchar(20) NOT NULL DEFAULT 'QUEUED',
  attempt integer NOT NULL DEFAULT 0,
  processing_status varchar(16) NOT NULL DEFAULT 'NONE',
  available_at timestamptz NOT NULL DEFAULT now(),
  hold_reason varchar(32),
  worker_id varchar(255),
  idempotency_key varchar(255),
  trace_id varchar(32) NOT NULL,
  input jsonb NOT NULL,
  config_snapshot jsonb NOT NULL,
  capture jsonb,
  output jsonb,
  exit_code integer,
  error_message text,
  cancellation_reason varchar(32),
  conversation_prepared_at timestamptz,
  practice_page_prepared_at timestamptz,
  public_review_digest varchar(64),
  admission_attempt integer,
  admission_digest varchar(64),
  llm_calls integer NOT NULL DEFAULT 0,
  llm_input_tokens bigint NOT NULL DEFAULT 0,
  llm_output_tokens bigint NOT NULL DEFAULT 0,
  llm_reasoning_tokens bigint NOT NULL DEFAULT 0,
  llm_cache_read_tokens bigint NOT NULL DEFAULT 0,
  llm_cache_write_tokens bigint NOT NULL DEFAULT 0,
  started_at timestamptz,
  execution_started_at timestamptz,
  completed_at timestamptz,
  CONSTRAINT ck_review_job_cancellation CHECK(cancellation_reason IS NULL OR cancellation_reason IN ('DRAIN_GRACEFUL','DRAIN_IMMEDIATE','BUDGET_EXHAUSTED','MODEL_UNAVAILABLE','MEMBER_AI_DECLINED','PERSON_DATA_ERASED','CANCELLED_BY_ADMIN','CANCELLED_BY_REQUESTER','CONTRACT_CHANGED')),
  CONSTRAINT uk_review_job_workspace UNIQUE(id, workspace_id),
  CONSTRAINT sfk_review_job_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_job_review FOREIGN KEY(review_id, workspace_id) REFERENCES review(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT ck_review_job_status CHECK(status IN ('QUEUED','RUNNING','COMPLETED','FAILED','TIMED_OUT','CANCELLED')),
  CONSTRAINT ck_review_job_processing CHECK(processing_status IN ('NONE','PENDING','DONE','FAILED')),
  CONSTRAINT ck_review_job_attempt CHECK(attempt >= 0),
  CONSTRAINT ck_review_job_admission CHECK((admission_attempt IS NULL) = (admission_digest IS NULL)),
  CONSTRAINT ck_review_job_input CHECK(jsonb_typeof(input)='object'),
  CONSTRAINT ck_review_job_config CHECK(jsonb_typeof(config_snapshot)='object')
);


CREATE TABLE review_job_script_run (
  job_id uuid NOT NULL,
  attempt integer NOT NULL,
  practice_id bigint NOT NULL,
  workspace_id bigint NOT NULL,
  practice_version_id bigint NOT NULL,
  status varchar(16) NOT NULL,
  script_kind varchar(16) NOT NULL,
  stop_reason varchar(32),
  calls jsonb,
  models jsonb,
  finished_at timestamptz NOT NULL,
  error varchar(500),
  duration_ms integer,
  PRIMARY KEY(attempt, job_id, practice_id),
  CONSTRAINT sfk_review_job_script_run_job FOREIGN KEY(job_id, workspace_id) REFERENCES review_job(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT sfk_review_job_script_run_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_job_script_run_version FOREIGN KEY(practice_version_id, practice_id, workspace_id)
    REFERENCES practice_version(id, practice_id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT ck_review_job_script_run_status CHECK(status IN ('OK','WITHHELD','FAILED','NOT_REACHED','NOT_FINISHED')),
  CONSTRAINT ck_review_job_script_run_reason CHECK(stop_reason IS NULL OR stop_reason IN
    ('UNAVAILABLE','BUDGET','DEADLINE','TOO_LARGE','OFF_FORMAT','REFUSED','ERROR','CANCELLED','INVALID_SCRIPT','INVALID_CANDIDATE')),
  CONSTRAINT ck_review_job_script_run_kind CHECK(script_kind IN ('BUILTIN','CUSTOM')),
  CONSTRAINT ck_review_job_script_run_counts CHECK(attempt>=0 AND (duration_ms IS NULL OR duration_ms>=0)),
  CONSTRAINT ck_review_job_script_run_models CHECK(models IS NULL OR jsonb_typeof(models)='array'),
  CONSTRAINT ck_review_job_script_run_calls CHECK(calls IS NULL OR jsonb_typeof(calls)='object')
);


CREATE TABLE review_job_script_usage (
  job_id uuid NOT NULL,
  attempt integer NOT NULL,
  model_kind varchar(16) NOT NULL,
  practice_id bigint NOT NULL,
  workspace_id bigint NOT NULL,
  data_handling_tier varchar(24),
  calls integer NOT NULL DEFAULT 0,
  reported_calls integer NOT NULL DEFAULT 0,
  input_tokens bigint NOT NULL DEFAULT 0,
  output_tokens bigint NOT NULL DEFAULT 0,
  cache_read_tokens bigint NOT NULL DEFAULT 0,
  cache_write_tokens bigint NOT NULL DEFAULT 0,
  search_units bigint NOT NULL DEFAULT 0,
  PRIMARY KEY(attempt, job_id, model_kind, practice_id),
  CONSTRAINT sfk_review_job_script_usage_job FOREIGN KEY(job_id, workspace_id) REFERENCES review_job(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT sfk_review_job_script_usage_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_review_job_script_usage_practice FOREIGN KEY(practice_id, workspace_id) REFERENCES practice(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT ck_review_job_script_usage_kind CHECK(model_kind IN ('CHAT','DECISION','EMBEDDING','RERANKING')),
  CONSTRAINT ck_review_job_script_usage_tier CHECK(data_handling_tier IS NULL OR data_handling_tier IN ('IN_HOUSE','CLOUD','UNDECLARED')),
  CONSTRAINT ck_review_job_script_usage_counts CHECK(attempt>=0 AND calls>=0 AND reported_calls>=0
    AND reported_calls<=calls AND input_tokens>=0 AND output_tokens>=0 AND cache_read_tokens>=0
    AND cache_write_tokens>=0 AND search_units>=0)
);


CREATE TABLE review_composition_basis (
 job_id uuid PRIMARY KEY,workspace_id bigint NOT NULL,
 admission_attempt integer NOT NULL,admission_digest varchar(64) NOT NULL,
 basis_digest varchar(64) NOT NULL,basis_version integer NOT NULL,
 copy_id uuid NOT NULL,expires_at timestamptz NOT NULL,payload jsonb NOT NULL,
 CONSTRAINT uk_review_composition_basis_workspace UNIQUE(job_id,workspace_id),
 CONSTRAINT sfk_review_composition_basis_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
 CONSTRAINT sfk_review_composition_basis_job FOREIGN KEY(job_id,workspace_id)
   REFERENCES review_job(id,workspace_id) ON DELETE CASCADE,
 CONSTRAINT ck_review_composition_basis_shape CHECK(admission_attempt>=0 AND basis_version>0 AND jsonb_typeof(payload)='object')
);








CREATE TABLE result (
  id uuid PRIMARY KEY,
  workspace_id bigint NOT NULL,
  review_id uuid NOT NULL,
  practice_id bigint NOT NULL,
  practice_version_id bigint,
  item_id bigint NOT NULL,
  item_version text,
  developer_id bigint,
  outcome varchar(24) NOT NULL,
  severity varchar(16),
  summary varchar(255),
  explanation text,
  evidence jsonb,
  example jsonb,
  coverage jsonb,
  evidence_version smallint NOT NULL DEFAULT 1,
  recorded_at timestamptz NOT NULL,
  ended_at timestamptz,
  end_reason varchar(24),
  CONSTRAINT uk_result_workspace UNIQUE(id, workspace_id),
  CONSTRAINT uk_result_assignment UNIQUE(id,practice_id,item_id,workspace_id),
  CONSTRAINT uk_result_developer UNIQUE(id, developer_id, workspace_id),
  CONSTRAINT sfk_result_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_result_review FOREIGN KEY(review_id, workspace_id) REFERENCES review(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_result_item FOREIGN KEY(item_id, workspace_id) REFERENCES item(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_result_practice FOREIGN KEY(practice_id, workspace_id) REFERENCES practice(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_result_version FOREIGN KEY(practice_version_id, practice_id, workspace_id)
    REFERENCES practice_version(id, practice_id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_result_developer FOREIGN KEY(workspace_id, developer_id)
    REFERENCES membership(workspace_id, account_id) ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT ck_result_outcome CHECK(outcome IN ('MET','NOT_MET','DOES_NOT_APPLY','COULD_NOT_DETERMINE')),
  CONSTRAINT ck_result_severity CHECK(severity IS NULL OR severity IN ('CRITICAL','MAJOR','MINOR','TRIVIAL')),
  CONSTRAINT ck_result_summary CHECK(outcome='MET' OR (summary IS NOT NULL AND btrim(summary)<>'')),
  CONSTRAINT ck_result_example CHECK(example IS NULL OR
    (outcome IN ('MET','NOT_MET') AND jsonb_typeof(example)='object')),
  CONSTRAINT ck_result_evidence_type CHECK(evidence IS NULL OR jsonb_typeof(evidence)='object'),
  CONSTRAINT ck_result_coverage_type CHECK(coverage IS NULL OR jsonb_typeof(coverage)='object'),
  CONSTRAINT ck_result_evidence_version CHECK(evidence_version IN (0,1)),
  CONSTRAINT ck_result_bound_version CHECK(evidence_version=0 OR (practice_version_id IS NOT NULL AND item_version IS NOT NULL)),
  CONSTRAINT ck_result_coverage CHECK(evidence_version=0 OR outcome<>'MET' OR coverage IS NOT NULL),
  CONSTRAINT ck_result_question_type CHECK(evidence_version=0 OR NOT(jsonb_exists(evidence, 'openQuestions')) OR jsonb_typeof(evidence->'openQuestions')='array'),
  CONSTRAINT ck_result_open_questions CHECK(evidence_version=0 OR
    CASE WHEN outcome='COULD_NOT_DETERMINE' THEN
      CASE WHEN jsonb_typeof(evidence->'openQuestions')='array' THEN jsonb_array_length(evidence->'openQuestions')>0 ELSE false END
    WHEN outcome='NOT_MET' THEN true ELSE
      CASE WHEN jsonb_typeof(evidence->'openQuestions')='array' THEN jsonb_array_length(evidence->'openQuestions')=0 ELSE true END END),
  CONSTRAINT ck_result_inapplicability CHECK(evidence_version=0 OR
    COALESCE(jsonb_typeof(evidence->'inapplicability')='object',false) = (outcome='DOES_NOT_APPLY')),
  CONSTRAINT ck_result_end CHECK((ended_at IS NULL) = (end_reason IS NULL)),
  CONSTRAINT ck_result_end_reason CHECK(end_reason IS NULL OR end_reason IN
    ('REPLACED','OUTRANKED','WORK_CHANGED','REPAIRED','REMOVED')),
  CONSTRAINT ck_result_dates CHECK(ended_at IS NULL OR ended_at>=recorded_at)
);


CREATE TABLE problem (
  id uuid PRIMARY KEY,
  workspace_id bigint NOT NULL,
  result_id uuid NOT NULL,
  position integer NOT NULL,
  key varchar(64),
  severity varchar(16) NOT NULL,
  summary varchar(255) NOT NULL,
  explanation text NOT NULL,
  citations jsonb NOT NULL,
  basis jsonb,
  next_step text,
  CONSTRAINT uk_problem_workspace UNIQUE(id, workspace_id),
  CONSTRAINT uk_problem_parent UNIQUE(id, result_id, workspace_id),
  CONSTRAINT uk_problem_position UNIQUE(result_id, position),
  CONSTRAINT uk_problem_key UNIQUE(result_id, key),
  CONSTRAINT sfk_problem_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_problem_result FOREIGN KEY(result_id, workspace_id) REFERENCES result(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT ck_problem_position CHECK(position>=0),
  CONSTRAINT ck_problem_key CHECK(key IS NULL OR key ~ '^[a-z0-9][a-z0-9-]{0,63}$'),
  CONSTRAINT ck_problem_severity CHECK(severity IN ('CRITICAL','MAJOR','MINOR','TRIVIAL')),
  CONSTRAINT ck_problem_citations CHECK(jsonb_typeof(citations)='array'),
  CONSTRAINT ck_problem_basis CHECK(basis IS NULL OR jsonb_typeof(basis)='object')
);


CREATE TABLE result_mark (
  id uuid PRIMARY KEY,
  workspace_id bigint NOT NULL,
  result_id uuid NOT NULL,
  kind varchar(16) NOT NULL DEFAULT 'INCORRECT',
  reason varchar(500) NOT NULL,
  created_by_id bigint,
  created_at timestamptz NOT NULL DEFAULT now(),
  removed_by_id bigint,
  removed_at timestamptz,
  removal_reason varchar(500),
  CONSTRAINT uk_result_mark_workspace UNIQUE(id, workspace_id),
  CONSTRAINT sfk_result_mark_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_result_mark_result FOREIGN KEY(result_id, workspace_id) REFERENCES result(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT sfk_result_mark_creator FOREIGN KEY(created_by_id) REFERENCES account(id) ON DELETE SET NULL,
  CONSTRAINT sfk_result_mark_remover FOREIGN KEY(removed_by_id) REFERENCES account(id) ON DELETE SET NULL,
  CONSTRAINT ck_result_mark_kind CHECK(kind IN ('INCORRECT','ACCEPTED')),
  CONSTRAINT ck_result_mark_reason CHECK(btrim(reason)<>''),
  CONSTRAINT ck_result_mark_removed CHECK((removed_at IS NULL) = (removal_reason IS NULL) AND (removal_reason IS NULL OR btrim(removal_reason)<>'')),
  CONSTRAINT ck_result_mark_dates CHECK(removed_at IS NULL OR removed_at>=created_at)
);


CREATE TABLE review_item (
 workspace_id bigint NOT NULL,review_id uuid NOT NULL,practice_id bigint NOT NULL,item_id bigint NOT NULL,
 item_version text,state varchar(16) NOT NULL DEFAULT 'LISTED',result_id uuid,job_id uuid,
 attempted_at timestamptz,reason varchar(128),detail jsonb,
 PRIMARY KEY(review_id,practice_id,item_id),
 CONSTRAINT uk_review_item_workspace UNIQUE(review_id,practice_id,item_id,workspace_id),
 CONSTRAINT sfk_review_item_workspace FOREIGN KEY(workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
 CONSTRAINT sfk_review_item_practice FOREIGN KEY(review_id,practice_id,workspace_id)
   REFERENCES review_practice(review_id,practice_id,workspace_id) ON DELETE CASCADE,
 CONSTRAINT sfk_review_item_item FOREIGN KEY(item_id,workspace_id) REFERENCES item(id,workspace_id) ON DELETE RESTRICT,
 CONSTRAINT sfk_review_item_result FOREIGN KEY(result_id,practice_id,item_id,workspace_id)
   REFERENCES result(id,practice_id,item_id,workspace_id) ON DELETE RESTRICT,
 CONSTRAINT sfk_review_item_job FOREIGN KEY(job_id,workspace_id)
   REFERENCES review_job(id,workspace_id) ON DELETE SET NULL(job_id),
 CONSTRAINT ck_review_item_state CHECK(state IN ('LISTED','JUDGED','REUSED','WITHHELD')),
 CONSTRAINT ck_review_item_result CHECK((state IN ('JUDGED','REUSED'))=(result_id IS NOT NULL)),
 CONSTRAINT ck_review_item_reason CHECK((state='WITHHELD')=(reason IS NOT NULL) AND (reason IS NULL OR btrim(reason)<>'')),
 CONSTRAINT ck_review_item_detail CHECK(detail IS NULL OR (jsonb_typeof(detail)='object' AND octet_length(detail::text)<=8192)),
 CONSTRAINT ck_review_item_version CHECK(item_version IS NULL OR (btrim(item_version)<>'' AND length(item_version)<=1024))
);


CREATE TABLE feedback (
  id uuid PRIMARY KEY,
  workspace_id bigint NOT NULL,
  review_id uuid NOT NULL,
  item_id bigint,
  developer_id bigint NOT NULL,
  destination varchar(24) NOT NULL,
  state varchar(24) NOT NULL,
  stop_reason varchar(48),
  body text,
  checks jsonb NOT NULL DEFAULT '{}'::jsonb,
  replaces_id uuid,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  delivered_at timestamptz,
  CONSTRAINT uk_feedback_workspace_id UNIQUE (id, workspace_id),
  CONSTRAINT uk_feedback_developer UNIQUE (id, developer_id, workspace_id),
  CONSTRAINT sfk_feedback_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_feedback_review FOREIGN KEY (review_id, workspace_id) REFERENCES review(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_feedback_item FOREIGN KEY (item_id, workspace_id) REFERENCES item(id, workspace_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_feedback_developer FOREIGN KEY (workspace_id, developer_id) REFERENCES membership(workspace_id, account_id) ON DELETE RESTRICT,
  CONSTRAINT sfk_feedback_replaces FOREIGN KEY (replaces_id, workspace_id)
    REFERENCES feedback(id, workspace_id) ON DELETE SET NULL (replaces_id),
  CONSTRAINT ck_feedback_destination CHECK (destination IN ('ON_WORK','PRACTICE_PAGE','CONVERSATION')),
  CONSTRAINT ck_feedback_item CHECK (destination <> 'ON_WORK' OR item_id IS NOT NULL),
  CONSTRAINT ck_feedback_state CHECK (state IN ('AWAITING_APPROVAL','READY','DELIVERED','UNCONFIRMED','WITHHELD','REJECTED','REPLACED','FAILED')),
  CONSTRAINT ck_feedback_withheld CHECK (state <> 'WITHHELD' OR stop_reason IS NOT NULL),
  CONSTRAINT ck_feedback_delivered CHECK (state <> 'DELIVERED' OR delivered_at IS NOT NULL),
  CONSTRAINT ck_feedback_checks CHECK (jsonb_typeof(checks) = 'object'),
  CONSTRAINT ck_feedback_replaces_self CHECK (replaces_id IS NULL OR replaces_id <> id),
 CONSTRAINT ck_feedback_stop_reason CHECK(stop_reason IS NULL OR stop_reason IN ('VOLUME_CAPPED','COMPOSER_WITHHELD','NOTHING_NEW','REPEATS_DELIVERED_NOTE','REACTED_DISAGREE','REACTED_NOT_APPLICABLE','CONVERSATION_EXPIRED','DELIVERY_UNCONFIRMED','ITEM_GONE','ITEM_CLOSED','ITEM_MERGED','ITEM_STATE_INELIGIBLE','ISSUE_SNAPSHOT_CHANGED','PUBLIC_SUBJECT_INELIGIBLE','NO_AI','DELIVERY_OFF','PERSON_SUPPRESSED','RECIPIENT_UNAVAILABLE','EMPTY_AFTER_SANITIZE','INSTANCE_SILENCED','FEEDBACK_OFF','WORKSPACE_DISABLED','WORKSPACE_DELIVERY_PAUSED','STALE_ROLLOUT_REVISION','OUTSIDE_CURRENT_SCOPE','APPROVAL_STALE','APPROVAL_NO_LONGER_ELIGIBLE','PRACTICE_REQUIRES_APPROVAL','BACKFILL_QUIET','RESULT_MARKED_INCORRECT','REVIEWED_VERSION_CHANGED','REVIEW_CANCELLED','EVIDENCE_NOT_PERMITTED','NO_EVIDENCE','UNCORROBORATED'))
);


CREATE TABLE feedback_basis (
  id uuid PRIMARY KEY,
  workspace_id bigint NOT NULL,
  feedback_id uuid NOT NULL,
  result_id uuid NOT NULL,
  problem_id uuid,
  developer_id bigint NOT NULL,
  ordinal integer NOT NULL,
  CONSTRAINT uk_feedback_basis_workspace_id UNIQUE (id, workspace_id),
  CONSTRAINT uk_feedback_basis_ref UNIQUE NULLS NOT DISTINCT (feedback_id, result_id, problem_id),
  CONSTRAINT sfk_feedback_basis_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_feedback_basis_feedback FOREIGN KEY (feedback_id, workspace_id)
    REFERENCES feedback(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT sfk_feedback_basis_result FOREIGN KEY (result_id, workspace_id)
    REFERENCES result(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT sfk_feedback_basis_result_person FOREIGN KEY (result_id, developer_id, workspace_id)
    REFERENCES result(id, developer_id, workspace_id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT sfk_feedback_basis_feedback_person FOREIGN KEY (feedback_id, developer_id, workspace_id)
    REFERENCES feedback(id, developer_id, workspace_id) ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT sfk_feedback_basis_problem FOREIGN KEY (problem_id, result_id, workspace_id)
    REFERENCES problem(id, result_id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT ck_feedback_basis_ordinal CHECK (ordinal >= 0)
);


CREATE TABLE feedback_copy (
  id uuid PRIMARY KEY,
  workspace_id bigint NOT NULL,
  feedback_id uuid NOT NULL,
  kind varchar(16) NOT NULL,
  position integer NOT NULL,
  body text,
  path text,
  start_line integer, end_line integer,
  side varchar(3),
  stop_reason varchar(48), readback varchar(16), last_error varchar(512),
  state varchar(16) NOT NULL DEFAULT 'PLANNED',
  write_started_at timestamptz,
  write_key text, write_marker text,
  external_ref text, external_url text,
  chat_message_id uuid,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  posted_at timestamptz,
  CONSTRAINT uk_feedback_copy_workspace_id UNIQUE (id, workspace_id),
  CONSTRAINT uk_feedback_copy_position UNIQUE (feedback_id, position),
  CONSTRAINT uk_feedback_copy_external UNIQUE (feedback_id, external_ref),
  CONSTRAINT sfk_feedback_copy_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_feedback_copy_feedback FOREIGN KEY (feedback_id, workspace_id)
    REFERENCES feedback(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT sfk_feedback_copy_chat FOREIGN KEY (chat_message_id, workspace_id)
    REFERENCES chat_message(id, workspace_id) ON DELETE SET NULL (chat_message_id),
  CONSTRAINT ck_feedback_copy_readback CHECK(readback IS NULL OR readback IN ('ABSENT','TRANSIENT','UNKNOWN')),
  CONSTRAINT ck_feedback_copy_kind CHECK (kind IN ('SUMMARY','LINE_NOTE','FILE_NOTE','CHAT_TURN')),
  CONSTRAINT ck_feedback_copy_side CHECK(side IS NULL OR side IN ('OLD','NEW')),
  CONSTRAINT ck_feedback_copy_side_scope CHECK(kind IN ('LINE_NOTE','FILE_NOTE') OR side IS NULL),
  CONSTRAINT ck_feedback_copy_state CHECK (state IN ('PLANNED','WRITE_STARTED','POSTED','FAILED','WITHHELD','RETRACTED')),
  CONSTRAINT ck_feedback_copy_position CHECK (position >= 0),
  CONSTRAINT ck_feedback_copy_anchor CHECK (
    (kind IN ('SUMMARY','CHAT_TURN') AND path IS NULL AND start_line IS NULL AND end_line IS NULL) OR
    (kind = 'FILE_NOTE' AND path IS NOT NULL AND ((start_line IS NULL AND end_line IS NULL) OR (start_line IS NOT NULL AND end_line IS NOT NULL AND start_line > 0 AND end_line >= start_line))) OR
    (kind = 'LINE_NOTE' AND path IS NOT NULL AND start_line IS NOT NULL AND end_line IS NOT NULL AND start_line > 0 AND end_line >= start_line)),
  CONSTRAINT ck_feedback_copy_summary_body CHECK (kind <> 'SUMMARY' OR body IS NULL),
  CONSTRAINT ck_feedback_copy_fence CHECK (state <> 'WRITE_STARTED' OR write_started_at IS NOT NULL),
  CONSTRAINT ck_feedback_copy_posted CHECK (state NOT IN ('POSTED','RETRACTED') OR posted_at IS NOT NULL),
 CONSTRAINT ck_feedback_copy_stop_reason CHECK(stop_reason IS NULL OR stop_reason IN ('VOLUME_CAPPED','COMPOSER_WITHHELD','NOTHING_NEW','REPEATS_DELIVERED_NOTE','REACTED_DISAGREE','REACTED_NOT_APPLICABLE','CONVERSATION_EXPIRED','DELIVERY_UNCONFIRMED','ITEM_GONE','ITEM_CLOSED','ITEM_MERGED','ITEM_STATE_INELIGIBLE','ISSUE_SNAPSHOT_CHANGED','PUBLIC_SUBJECT_INELIGIBLE','NO_AI','DELIVERY_OFF','PERSON_SUPPRESSED','RECIPIENT_UNAVAILABLE','EMPTY_AFTER_SANITIZE','INSTANCE_SILENCED','FEEDBACK_OFF','WORKSPACE_DISABLED','WORKSPACE_DELIVERY_PAUSED','STALE_ROLLOUT_REVISION','OUTSIDE_CURRENT_SCOPE','APPROVAL_STALE','APPROVAL_NO_LONGER_ELIGIBLE','PRACTICE_REQUIRES_APPROVAL','BACKFILL_QUIET','RESULT_MARKED_INCORRECT','REVIEWED_VERSION_CHANGED','REVIEW_CANCELLED','EVIDENCE_NOT_PERMITTED','NO_EVIDENCE','UNCORROBORATED'))
);


CREATE TABLE feedback_send (
  feedback_id uuid PRIMARY KEY,
  workspace_id bigint NOT NULL,
  action varchar(8) NOT NULL DEFAULT 'POST',
  state varchar(16) NOT NULL DEFAULT 'PENDING',
  lease_owner varchar(64), lease_expires_at timestamptz,
  attempts integer NOT NULL DEFAULT 0,
  next_attempt_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_error varchar(512),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_feedback_send_workspace_id UNIQUE (feedback_id, workspace_id),
  CONSTRAINT sfk_feedback_send_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_feedback_send_feedback FOREIGN KEY (feedback_id, workspace_id)
    REFERENCES feedback(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT ck_feedback_send_action CHECK (action IN ('POST','RETRACT')),
  CONSTRAINT ck_feedback_send_state CHECK (state IN ('PENDING','SENDING','UNCERTAIN','DONE')),
  CONSTRAINT ck_feedback_send_attempts CHECK (attempts >= 0),
  CONSTRAINT ck_feedback_send_lease CHECK ((state = 'SENDING') = (lease_owner IS NOT NULL AND lease_expires_at IS NOT NULL)),
  CONSTRAINT ck_feedback_send_lease_pair CHECK ((lease_owner IS NULL) = (lease_expires_at IS NULL))
);


CREATE TABLE feedback_decision (
  id uuid PRIMARY KEY,
  workspace_id bigint NOT NULL,
  feedback_id uuid NOT NULL,
  action varchar(8) NOT NULL,
  actor_account_id bigint,
  reason varchar(500), note text,
  content_digest varchar(64),
  decided_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_feedback_decision_workspace_id UNIQUE (id, workspace_id),
  CONSTRAINT sfk_feedback_decision_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_feedback_decision_feedback FOREIGN KEY (feedback_id, workspace_id)
    REFERENCES feedback(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT sfk_feedback_decision_actor FOREIGN KEY (actor_account_id) REFERENCES account(id) ON DELETE SET NULL,
  CONSTRAINT ck_feedback_decision_action CHECK (action IN ('APPROVE','REJECT','WITHDRAW','RESTORE')),
  CONSTRAINT ck_feedback_decision_digest CHECK (content_digest IS NULL OR content_digest ~ '^[0-9a-f]{64}$'),
  CONSTRAINT ck_feedback_decision_approval_digest CHECK (action NOT IN ('APPROVE','REJECT') OR content_digest IS NOT NULL),
  CONSTRAINT ck_feedback_decision_approve_reason CHECK (action <> 'APPROVE' OR reason IS NULL)
);


CREATE TABLE feedback_response (
  id uuid PRIMARY KEY,
  workspace_id bigint NOT NULL,
  feedback_id uuid NOT NULL,
  resolution varchar(16), usefulness varchar(16), comment text,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uk_feedback_response_workspace_id UNIQUE (id, workspace_id),
  CONSTRAINT sfk_feedback_response_workspace FOREIGN KEY (workspace_id) REFERENCES workspace(id) ON DELETE RESTRICT,
  CONSTRAINT sfk_feedback_response_feedback FOREIGN KEY (feedback_id, workspace_id)
    REFERENCES feedback(id, workspace_id) ON DELETE CASCADE,
  CONSTRAINT ck_feedback_response_resolution CHECK (resolution IS NULL OR resolution IN ('ADDRESSED','DISAGREE','NOT_APPLICABLE')),
  CONSTRAINT ck_feedback_response_usefulness CHECK (usefulness IS NULL OR usefulness IN ('HELPFUL','UNHELPFUL')),
  CONSTRAINT ck_feedback_response_disagree CHECK (resolution IS DISTINCT FROM 'DISAGREE' OR nullif(btrim(comment), '') IS NOT NULL)
);






DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_old_observation o JOIN _cutover_old_agent_job j ON j.id=o.agent_job_id
           WHERE o.workspace_id<>j.workspace_id) THEN
   RAISE EXCEPTION '_cutover_old_observation/job workspace mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_observation o JOIN _cutover_old_practice p ON p.id=o.practice_id
           WHERE p.workspace_id<>o.workspace_id) THEN
   RAISE EXCEPTION '_cutover_old_observation/_cutover_old_practice workspace mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_observation o WHERE NOT EXISTS
           (SELECT 1 FROM _cutover_old_agent_job j WHERE j.id=o.agent_job_id)) THEN
   RAISE EXCEPTION '_cutover_old_observation has no source job'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_observation o JOIN _cutover_old_practice_revision v ON v.id=o.practice_revision_id
           WHERE v.practice_id<>o.practice_id) THEN
   RAISE EXCEPTION '_cutover_old_observation version belongs to another _cutover_old_practice'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_observation WHERE outcome NOT IN ('MET','NOT_MET','NOT_APPLICABLE','UNDETERMINED')
           OR (outcome='NOT_MET')<>(severity IS NOT NULL)) THEN
   RAISE EXCEPTION 'invalid released outcome/severity'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_observation WHERE evidence IS NOT NULL AND jsonb_typeof(evidence)<>'object') THEN
   RAISE EXCEPTION 'invalid released evidence object'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_observation WHERE evidence ? 'citations'
           AND jsonb_typeof(evidence->'citations') NOT IN ('array','null')) THEN
   RAISE EXCEPTION 'invalid released citations'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_observation WHERE evidence ? 'undecidability'
           AND jsonb_typeof(evidence->'undecidability') NOT IN ('object','array','null')) THEN
   RAISE EXCEPTION 'invalid released open-question warrant'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_observation GROUP BY agent_job_id,practice_id,artifact_kind,artifact_id,about_user_id
           HAVING count(*)>1) THEN
   RAISE EXCEPTION 'released duplicate result grain'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_artifact_signal WHERE signal_name='scm.pull_request.reviewed'
           AND revision !~ '^event~[1-9][0-9]*$') THEN
   RAISE EXCEPTION 'reviewer event has no exact pull request review id'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_identity_link GROUP BY provider_id,subject,COALESCE(team_id,'')
           HAVING count(DISTINCT account_id)>1) THEN
   RAISE EXCEPTION 'provider identity assigned to several accounts'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_person_suppression s JOIN _cutover_old_public_activity_objection o ON o.id=s.id) THEN
   RAISE EXCEPTION 'restriction UUID collision'; END IF;
 IF EXISTS(SELECT 1 FROM sync_job s WHERE s.triggered_by_user_id IS NOT NULL
           AND NOT EXISTS(SELECT 1 FROM account a WHERE a.id=s.triggered_by_user_id)) THEN
   RAISE EXCEPTION 'sync requester is not an account'; END IF;
END $$;

CREATE TEMP TABLE _needed_user(user_id bigint PRIMARY KEY) ON COMMIT DROP;
INSERT INTO _needed_user
 SELECT user_id FROM _cutover_old_workspace_membership
 UNION SELECT user_id FROM _cutover_old_workspace_hidden_former_member
 UNION SELECT user_id FROM _cutover_old_practice_review_person_target
 UNION SELECT user_id FROM _cutover_old_user_preferences
 UNION SELECT about_user_id FROM _cutover_old_observation
 UNION SELECT recipient_user_id FROM _cutover_old_feedback
 UNION SELECT about_user_id FROM _cutover_old_feedback
 UNION SELECT reactor_user_id FROM _cutover_old_reaction
 UNION SELECT user_id FROM chat_thread WHERE user_id IS NOT NULL
 UNION SELECT e.viewed_user_id FROM auth_event e JOIN "user" u ON u.id=e.viewed_user_id WHERE upper(u.type)='USER'
 UNION SELECT author_member_id FROM slack_message WHERE author_member_id IS NOT NULL
 UNION SELECT unnest(participant_member_ids) FROM slack_thread
 UNION SELECT actor_user_id FROM slack_channel_consent_event WHERE actor_user_id IS NOT NULL
 UNION SELECT requested_by_user_id FROM _cutover_old_artifact_signal WHERE requested_by_user_id IS NOT NULL
 UNION SELECT NULLIF(metadata->>'about_user_id','')::bigint FROM _cutover_old_agent_job WHERE metadata->>'about_user_id' IS NOT NULL;

-- Roster-only non-human rows are provider facts, not members in the account model.
DELETE FROM _needed_user n USING "user" u WHERE u.id=n.user_id AND upper(u.type) IN ('BOT','ORGANIZATION')
 AND NOT EXISTS(SELECT 1 FROM _cutover_old_observation o WHERE o.about_user_id=u.id)
 AND NOT EXISTS(SELECT 1 FROM _cutover_old_feedback f WHERE f.recipient_user_id=u.id OR f.about_user_id=u.id)
 AND NOT EXISTS(SELECT 1 FROM _cutover_old_reaction r WHERE r.reactor_user_id=u.id)
 AND NOT EXISTS(SELECT 1 FROM chat_thread t WHERE t.user_id=u.id)
 AND NOT EXISTS(SELECT 1 FROM slack_message m WHERE m.author_member_id=u.id)
 AND NOT EXISTS(SELECT 1 FROM slack_thread t WHERE u.id=ANY(t.participant_member_ids))
 AND NOT EXISTS(SELECT 1 FROM slack_channel_consent_event e WHERE e.actor_user_id=u.id)
 AND NOT EXISTS(SELECT 1 FROM _cutover_old_artifact_signal e WHERE e.requested_by_user_id=u.id)
 AND NOT EXISTS(SELECT 1 FROM _cutover_old_agent_job j WHERE j.metadata->>'about_user_id'=u.id::text);

DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _needed_user n LEFT JOIN "user" u ON u.id=n.user_id
           WHERE u.id IS NULL) THEN RAISE EXCEPTION 'person reference has no SCM user'; END IF;
 IF EXISTS(SELECT 1 FROM _needed_user n JOIN "user" u ON u.id=n.user_id
           WHERE u.type IS NULL OR upper(u.type)<>'USER') THEN
   RAISE EXCEPTION 'person-owned row refers to a bot, organization, or unknown actor type'; END IF;
 IF EXISTS(SELECT 1 FROM _needed_user n JOIN "user" u ON u.id=n.user_id
           JOIN _cutover_old_person_suppression r ON r.provider_id=u.provider_id AND r.subject=u.native_id::text AND r.team_key='') THEN
   RAISE EXCEPTION 'person-owned data remains for an erased identity'; END IF;
 IF EXISTS(SELECT 1 FROM _needed_user n JOIN "user" u ON u.id=n.user_id
           JOIN _cutover_old_identity_link i ON i.provider_id=u.provider_id AND i.subject=u.native_id::text
           AND COALESCE(i.team_id,'')=''
           JOIN account a ON a.id=i.account_id WHERE a.status IN ('DELETING','DELETED')) THEN
   RAISE EXCEPTION 'person-owned data remains for an erased account'; END IF;
END $$;

CREATE TEMP TABLE _person_map(user_id bigint PRIMARY KEY,account_id bigint NOT NULL) ON COMMIT DROP;
INSERT INTO _person_map
 SELECT DISTINCT n.user_id,i.account_id FROM _needed_user n JOIN "user" u ON u.id=n.user_id
 JOIN _cutover_old_identity_link i ON i.provider_id=u.provider_id AND i.subject=u.native_id::text
 AND COALESCE(i.team_id,'')='';
SELECT pg_temp.cutover_align_sequence('account',NULL);
CREATE TEMP TABLE _new_person ON COMMIT DROP AS
 SELECT u.id AS user_id,nextval(pg_get_serial_sequence('account','id')) AS account_id,
        u.provider_id,u.native_id::text AS provider_user_key,
        left(COALESCE(NULLIF(u.name,''),NULLIF(u.login,''),'Workspace member'),255) AS display_name
 FROM _needed_user n JOIN "user" u ON u.id=n.user_id
 WHERE NOT EXISTS(SELECT 1 FROM _person_map m WHERE m.user_id=u.id);
INSERT INTO account(id,display_name,status,app_role,primary_email,created_at,updated_at,version)
 SELECT account_id,display_name,'UNCLAIMED','USER',NULL,c.at,c.at,0
 FROM _new_person CROSS JOIN _cutover_clock c;
INSERT INTO _person_map SELECT user_id,account_id FROM _new_person;

UPDATE account a SET ai_choice=x.ai_choice,ai_choice_at=x.updated_at
 FROM _cutover_old_account_ai_choice x WHERE x.account_id=a.id;
UPDATE account a SET feedback_delivery_enabled=x.enabled FROM
 (SELECT m.account_id,bool_and(p.ai_review_enabled) AS enabled
  FROM _cutover_old_user_preferences p JOIN _person_map m ON m.user_id=p.user_id GROUP BY m.account_id) x
 WHERE a.id=x.account_id;

INSERT INTO identity(id,account_id,provider_id,provider_user_key,team_key,linked_via,linked_at,last_login_at,disabled_at)
 SELECT id,account_id,provider_id,subject,COALESCE(team_id,''),
        CASE linked_via WHEN 'OAUTH_LOGIN' THEN 'SIGN_IN' WHEN 'MANUAL_LINK' THEN 'MANUAL' END,
        linked_at,last_login_at,disabled_at FROM _cutover_old_identity_link;
SELECT pg_temp.cutover_align_sequence('identity','identity_link');
INSERT INTO identity(account_id,provider_id,provider_user_key,team_key,linked_via,linked_at)
 SELECT account_id,provider_id,provider_user_key,'','ROSTER',c.at
 FROM _new_person CROSS JOIN _cutover_clock c;
INSERT INTO identity_restriction(id,provider_id,provider_user_key,team_key,kind,active_request_id)
 SELECT id,provider_id,subject,team_key,'ERASED',active_request_id FROM _cutover_old_person_suppression;
INSERT INTO identity_restriction(id,provider_id,provider_user_key,team_key,kind)
 SELECT id,provider_id,subject,'','HIDE_PUBLIC' FROM _cutover_old_public_activity_objection;
UPDATE account a SET public_activity_visible=false WHERE EXISTS
 (SELECT 1 FROM identity i JOIN identity_restriction r USING(provider_id,provider_user_key,team_key)
  WHERE i.account_id=a.id AND r.kind='HIDE_PUBLIC');

CREATE TEMP TABLE _membership_seed (
 workspace_id bigint,account_id bigint,role varchar(16),hidden boolean,selected boolean,
 joined_at timestamptz,active boolean
) ON COMMIT DROP;
INSERT INTO _membership_seed
 SELECT w.workspace_id,m.account_id,w.role,w.hidden,
        EXISTS(SELECT 1 FROM _cutover_old_practice_review_person_target t WHERE t.workspace_id=w.workspace_id AND t.user_id=w.user_id),
        w.created_at,true FROM _cutover_old_workspace_membership w JOIN _person_map m ON m.user_id=w.user_id;
INSERT INTO _membership_seed
 SELECT w.workspace_id,m.account_id,'MEMBER',true,false,c.at,false
 FROM _cutover_old_workspace_hidden_former_member w JOIN _person_map m ON m.user_id=w.user_id CROSS JOIN _cutover_clock c;
INSERT INTO _membership_seed
 SELECT o.workspace_id,m.account_id,'MEMBER',false,false,o.observed_at,false
 FROM _cutover_old_observation o JOIN _person_map m ON m.user_id=o.about_user_id
 UNION ALL
 SELECT f.workspace_id,m.account_id,'MEMBER',false,false,f.created_at,false
 FROM _cutover_old_feedback f JOIN _person_map m ON m.user_id=f.recipient_user_id
 UNION ALL
 SELECT t.workspace_id,m.account_id,'MEMBER',false,false,t.created_at,false
 FROM chat_thread t JOIN _person_map m ON m.user_id=t.user_id
 UNION ALL
 SELECT s.workspace_id,m.account_id,'MEMBER',false,false,s.ingested_at,false
 FROM slack_message s JOIN _person_map m ON m.user_id=s.author_member_id
 UNION ALL
 SELECT o.workspace_id,o.account_id,'MEMBER',false,false,o.updated_at,false
 FROM _cutover_old_workspace_member_onboarding o;
INSERT INTO membership(workspace_id,account_id,role,hidden,review_selected,joined_at,left_at)
 SELECT s.workspace_id,s.account_id,
        CASE max(CASE s.role WHEN 'OWNER' THEN 2 WHEN 'ADMIN' THEN 1 ELSE 0 END)
          WHEN 2 THEN 'OWNER' WHEN 1 THEN 'ADMIN' ELSE 'MEMBER' END,
        bool_or(s.hidden),bool_or(s.selected),min(s.joined_at),
        CASE WHEN bool_or(s.active) THEN NULL ELSE greatest(c.at,min(s.joined_at)) END
 FROM _membership_seed s CROSS JOIN _cutover_clock c GROUP BY s.workspace_id,s.account_id,c.at;
UPDATE membership m SET onboarding_seen_revision=o.seen_revision,public_activity_seen=o.public_activity_seen
 FROM _cutover_old_workspace_member_onboarding o WHERE o.workspace_id=m.workspace_id AND o.account_id=m.account_id;


CREATE FUNCTION pg_temp.cutover_definition(o jsonb) RETURNS jsonb
LANGUAGE sql IMMUTABLE STRICT AS $$
SELECT jsonb_build_object(
  'name', o -> 'name',
  'reviewOn', jsonb_build_object('events', o -> 'signals', 'state', o -> 'reviewWhen'),
  'appliesWhen', CASE WHEN o -> 'precondition' IS NULL OR o -> 'precondition' = 'null'::jsonb
    THEN 'null'::jsonb ELSE jsonb_build_object(
      'otherwise', o -> 'precondition' -> 'skipReason',
      'anyOf', (SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'changedPath', c -> 'changedPathMatches',
        'diffContains', c -> 'diffContains',
        'hasItems', c -> 'evidenceHasItems')) ORDER BY n), '[]'::jsonb)
        FROM jsonb_array_elements(o -> 'precondition' -> 'anyOf') WITH ORDINALITY AS x(c,n))) END,
  'about', o -> 'subject',
  'reads', jsonb_build_object(
    'contract', o -> 'automatedReviewPolicy' -> 'sourceContractVersion',
    'sources', CASE WHEN o -> 'evidenceRequirements' IS NULL OR o -> 'evidenceRequirements' = 'null'::jsonb
      THEN 'null'::jsonb ELSE
      (SELECT coalesce(jsonb_agg(jsonb_build_object(
        'source', e -> 'sourceKind', 'need', CASE e ->> 'stance'
          WHEN 'REQUIRED' THEN 'REQUIRED' WHEN 'EXHAUSTIVE' THEN 'COMPLETE' WHEN 'CONTEXTUAL' THEN 'OPTIONAL' END)
        ORDER BY e ->> 'sourceKind'), '[]'::jsonb)
       FROM jsonb_array_elements(o -> 'evidenceRequirements') AS x(e)) END),
  'reviewedBy', CASE WHEN o -> 'automatedReviewPolicy' IS NULL OR o -> 'automatedReviewPolicy' = 'null'::jsonb
    THEN 'null'::jsonb ELSE jsonb_build_object(
      'by', CASE o -> 'automatedReviewPolicy' -> 'automatedReview' ->> 'evidenceSufficiency'
        WHEN 'SUFFICIENT_WHEN_REQUIREMENTS_MET' THEN 'HEPHAESTUS'
        WHEN 'DECLARED_EVIDENCE_INSUFFICIENT' THEN 'PEOPLE'
        WHEN 'NONE' THEN 'NOBODY' END,
      'humanReason', o -> 'automatedReviewPolicy' -> 'insufficiencyReason',
      'limits', o -> 'automatedReviewPolicy' -> 'knownLimitations') END,
  'criteria', o -> 'criteria', 'script', o -> 'precomputeScript', 'scan', NULL,
  'lineNotes', NOT coalesce((o -> 'deliveryBehavior' ->> 'summaryOnly')::boolean, false),
  'guidance', jsonb_build_object('whyItMatters', o -> 'whyItMatters',
    'whatGoodLooksLike', o -> 'whatGoodLooksLike', 'goingWell', o -> 'holdsAs',
    'visual', o -> 'visual', 'guide', o -> 'guide'))
$$;

CREATE FUNCTION pg_temp.cutover_normalize(d jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT AS $$
DECLARE out_value jsonb:=d; x jsonb;
BEGIN
 IF jsonb_typeof(d->'reviewOn'->'events')='array' THEN
  SELECT coalesce(jsonb_agg(value ORDER BY value COLLATE "C"),'[]'::jsonb) INTO x
   FROM (SELECT DISTINCT regexp_replace(regexp_replace(value,'^chat\.conversation_thread\.','chat.thread.'),'^scm\.pull_request\.reviewed$','scm.pull_request_review.submitted') AS value
    FROM jsonb_array_elements_text(d->'reviewOn'->'events')) q;
  out_value:=jsonb_set(out_value,'{reviewOn,events}',x);
 END IF;
 IF jsonb_typeof(d->'reviewOn'->'state')='object' THEN
  SELECT coalesce(jsonb_object_agg(key,(SELECT jsonb_agg(value ORDER BY value COLLATE "C")
   FROM (SELECT DISTINCT value FROM jsonb_array_elements_text(q.value)) a)),'{}'::jsonb)
   INTO x FROM jsonb_each(d->'reviewOn'->'state') q;
  out_value:=jsonb_set(out_value,'{reviewOn,state}',x);
 END IF;
 IF jsonb_typeof(d->'reviewedBy'->'limits')='array' THEN
  SELECT coalesce(jsonb_agg(value ORDER BY value->>'code' COLLATE "C"),'[]'::jsonb) INTO x FROM jsonb_array_elements(d->'reviewedBy'->'limits');
  out_value:=jsonb_set(out_value,'{reviewedBy,limits}',x);
 END IF;
 RETURN out_value;
END $$;
CREATE FUNCTION pg_temp.cutover_columns(o jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE STRICT AS $$
 SELECT pg_temp.cutover_normalize(pg_temp.cutover_definition(jsonb_build_object(
 'name',o->'name','signals',o->'signals','reviewWhen',o->'review_when','subject',o->'subject',
 'precondition',o->'precondition','evidenceRequirements',o->'evidence_requirements','automatedReviewPolicy',o->'automated_review_policy',
 'criteria',o->'criteria','precomputeScript',o->'precompute_script','deliveryBehavior',o->'delivery_behavior',
 'whyItMatters',o->'why_it_matters','whatGoodLooksLike',o->'what_good_looks_like','visual',o->'visual','guide',o->'guide')))
 - CASE WHEN o->'subject' IS NULL OR o->'subject'='null'::jsonb THEN 'about' ELSE '_unknown' END
$$;
CREATE TEMP TABLE _cutover_bundle(entry_type varchar(16),slug varchar(64),kind varchar(64),old_definition jsonb,
 definition jsonb,old_review_fingerprint varchar(96),old_catalog_digest varchar(128),PRIMARY KEY(entry_type,slug)) ON COMMIT DROP;

CREATE FUNCTION pg_temp.cutover_kind(k text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE k WHEN 'chat.conversation_thread' THEN 'chat.thread' ELSE k END $$;


