CREATE FUNCTION pg_temp.cutover_authored_kind(k text,events jsonb,role_name text,bundled text) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE inferred text; n bigint; resolved text;
BEGIN
 IF events IS NOT NULL AND events<>'null'::jsonb THEN
  SELECT count(DISTINCT split_part(value,'.',1)||'.'||split_part(value,'.',2)),min(split_part(value,'.',1)||'.'||split_part(value,'.',2)) INTO n,inferred FROM jsonb_array_elements_text(events);
  IF n>1 THEN RAISE EXCEPTION 'authored events have conflicting item kinds'; END IF;
 END IF;
 IF k IS NOT NULL AND inferred IS NOT NULL AND pg_temp.cutover_kind(k)<>pg_temp.cutover_kind(inferred) THEN RAISE EXCEPTION 'authored kind conflicts with its events'; END IF;
 resolved:=pg_temp.cutover_kind(COALESCE(k,inferred,bundled));
 IF role_name='REVIEWER' THEN
  IF resolved<>'scm.pull_request' THEN RAISE EXCEPTION 'reviewer definition does not name a pull request'; END IF;
  RETURN 'scm.pull_request_review';
 END IF;
 IF resolved IS NULL THEN RAISE EXCEPTION 'local authored kind cannot be resolved from released facts'; END IF;
 RETURN resolved;
END $$;

CREATE FUNCTION pg_temp.cutover_catalog(d jsonb,k text,g text) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
 SELECT jsonb_build_object('kind',CASE WHEN d->>'subject'='REVIEWER' THEN 'scm.pull_request_review' ELSE CASE k WHEN 'chat.conversation_thread' THEN 'chat.thread' ELSE k END END,
  'groupSlug',g,'definition',pg_temp.cutover_normalize(pg_temp.cutover_definition(d)) - CASE WHEN d->'subject' IS NULL OR d->'subject'='null'::jsonb THEN 'about' ELSE '_unknown' END)
$$;
INSERT INTO practice_group(id,workspace_id,slug,name,description,icon,color,position,shown_to_developers,feedback_mode,catalog_slug,catalog_base,created_at,updated_at)
SELECT g.id,g.workspace_id,g.slug,g.name,g.description,g.icon,g.color,g.display_order,g.visible_in_practice_dashboards,
 CASE g.autonomy WHEN 'HUMAN_APPROVAL' THEN 'APPROVE_FIRST' ELSE g.autonomy END,g.source_curated_slug,
 CASE WHEN g.source_curated_slug IS NOT NULL THEN COALESCE(b.definition,jsonb_build_object('name',g.name,'description',g.description,'icon',g.icon,'color',g.color)) END,g.created_at,g.updated_at
FROM _cutover_old_practice_group g LEFT JOIN _cutover_bundle b ON b.entry_type='GROUP' AND b.slug=g.source_curated_slug AND b.old_review_fingerprint=g.source_curated_fingerprint;
UPDATE _cutover_sequence SET last_value=GREATEST(last_value,COALESCE((SELECT max(id) FROM _cutover_old_practice_revision),last_value)),is_called=is_called OR EXISTS(SELECT 1 FROM _cutover_old_practice_revision) WHERE table_name='practice_revision';
SELECT pg_temp.cutover_align_sequence('practice_version','practice_revision');
CREATE TEMP TABLE _cutover_initial_version ON COMMIT DROP AS SELECT id AS practice_id,
 COALESCE(current_revision_id,nextval(pg_get_serial_sequence('practice_version','id'))) AS id,
 current_revision_id IS NULL AS unbound FROM _cutover_old_practice;
ALTER TABLE _cutover_initial_version ADD PRIMARY KEY(practice_id);
INSERT INTO practice(id,workspace_id,slug,kind,group_id,position,current_version_id,feedback_mode,catalog_slug,catalog_base,created_at,updated_at)
SELECT p.id,p.workspace_id,p.slug,
 CASE p.subject WHEN 'REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(p.applies_to) END,
 p.practice_group_id,p.display_order,initial_version.id,
 CASE p.autonomy WHEN 'HUMAN_APPROVAL' THEN 'APPROVE_FIRST' ELSE p.autonomy END,p.source_curated_slug,
 CASE WHEN p.source_curated_slug IS NOT NULL THEN COALESCE(
  CASE WHEN p.declined_offered_digest=b.old_catalog_digest THEN jsonb_build_object('kind',CASE WHEN b.old_definition->>'subject'='REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(b.kind) END,'groupSlug',b.old_definition->'groupSlug','definition',b.definition) END,
  CASE WHEN p.adopted_base IS NOT NULL THEN pg_temp.cutover_catalog(p.adopted_base,p.applies_to,p.adopted_base->>'groupSlug') END,
  CASE WHEN b.old_review_fingerprint=p.source_curated_fingerprint THEN jsonb_build_object('kind',CASE WHEN b.old_definition->>'subject'='REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(b.kind) END,'groupSlug',b.old_definition->'groupSlug','definition',b.definition) END,
  (SELECT jsonb_build_object('kind',CASE v.subject WHEN 'REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(v.applies_to) END,'groupSlug',v.group_slug,'definition',pg_temp.cutover_columns(to_jsonb(v)))
   FROM _cutover_old_practice_revision v WHERE v.practice_id=p.id AND v.review_rule_fingerprint=p.source_curated_fingerprint AND v.name IS NOT NULL AND v.subject IS NOT NULL AND v.automated_review_policy IS NOT NULL AND v.signals IS NOT NULL AND v.review_when IS NOT NULL AND v.evidence_requirements IS NOT NULL ORDER BY v.revision_number,v.id LIMIT 1),
  jsonb_build_object('kind',CASE p.subject WHEN 'REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(p.applies_to) END,'groupSlug',g.slug,'definition',pg_temp.cutover_columns(to_jsonb(p)))) END,
 p.created_at,p.updated_at
FROM _cutover_old_practice p JOIN _cutover_initial_version initial_version ON initial_version.practice_id=p.id
LEFT JOIN _cutover_old_practice_group g ON g.id=p.practice_group_id
LEFT JOIN _cutover_bundle b ON b.entry_type='PRACTICE' AND b.slug=p.source_curated_slug;
INSERT INTO practice_version(id,workspace_id,practice_id,number,definition,created_at)
SELECT v.id,p.workspace_id,v.practice_id,v.revision_number,pg_temp.cutover_columns(to_jsonb(v)),v.created_at
FROM _cutover_old_practice_revision v JOIN _cutover_old_practice p ON p.id=v.practice_id;
INSERT INTO practice_version(id,workspace_id,practice_id,number,definition,created_at)
 SELECT i.id,p.workspace_id,p.id,COALESCE((SELECT max(v.revision_number)+1 FROM _cutover_old_practice_revision v WHERE v.practice_id=p.id),1),
 jsonb_set(pg_temp.cutover_columns(to_jsonb(p)),'{reads,contract}','"2.0.0"'::jsonb),c.at
 FROM _cutover_old_practice p JOIN _cutover_initial_version i ON i.practice_id=p.id AND i.unbound CROSS JOIN _cutover_clock c;
INSERT INTO catalog_entry(entry_type,slug,kind,definition,base,position,excluded_at,created_at,updated_at,version)
SELECT 'PRACTICE',o.slug,CASE WHEN o.name IS NOT NULL THEN pg_temp.cutover_authored_kind(o.applies_to,o.signals,o.subject,b.kind) END,
 CASE WHEN o.name IS NOT NULL THEN jsonb_build_object('groupSlug',o.group_slug,'definition',pg_temp.cutover_columns(to_jsonb(o))) END,
 CASE WHEN o.name IS NOT NULL THEN COALESCE(CASE WHEN o.based_on_digest=b.old_catalog_digest THEN jsonb_build_object('kind',CASE WHEN b.old_definition->>'subject'='REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(b.kind) END,'groupSlug',b.old_definition->'groupSlug','definition',b.definition) END,
 CASE WHEN o.adopted_base IS NOT NULL AND o.adopted_base<>'{}'::jsonb THEN pg_temp.cutover_catalog(o.adopted_base,COALESCE(o.applies_to,b.kind),o.adopted_base->>'groupSlug') END) END,
 o.position,o.retired_at,o.created_at,o.updated_at,o.version
FROM _cutover_old_curated_practice_override o LEFT JOIN _cutover_bundle b ON b.entry_type='PRACTICE' AND b.slug=o.slug;
INSERT INTO catalog_entry(entry_type,slug,definition,base,position,excluded_at,created_at,updated_at,version)
SELECT 'GROUP',o.slug,CASE WHEN o.name IS NOT NULL THEN jsonb_build_object('name',o.name,'description',o.description,'icon',o.icon,'color',o.color) END,
 CASE WHEN o.name IS NOT NULL AND o.based_on_digest=b.old_catalog_digest THEN b.definition END,
 o.position,o.retired_at,o.created_at,o.updated_at,o.version FROM _cutover_old_curated_group_override o LEFT JOIN _cutover_bundle b ON b.entry_type='GROUP' AND b.slug=o.slug;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM catalog_entry WHERE entry_type='PRACTICE' AND definition IS NOT NULL AND kind IS NULL) THEN RAISE EXCEPTION 'local catalog kind cannot be resolved'; END IF;
END $$;

CREATE TEMP TABLE _cutover_offer ON COMMIT DROP AS
 SELECT b.entry_type,b.slug,COALESCE(e.kind,CASE WHEN b.old_definition->>'subject'='REVIEWER' THEN 'scm.pull_request_review' ELSE pg_temp.cutover_kind(b.kind) END) AS kind,
 CASE WHEN b.entry_type='PRACTICE' THEN CASE WHEN e.definition IS NOT NULL THEN e.definition->>'groupSlug' ELSE b.old_definition->>'groupSlug' END END AS group_slug,
 CASE WHEN b.entry_type='PRACTICE' AND e.definition IS NOT NULL THEN e.definition->'definition' ELSE COALESCE(e.definition,b.definition) END AS definition
 FROM _cutover_bundle b LEFT JOIN catalog_entry e ON e.entry_type=b.entry_type AND e.slug=b.slug WHERE e.excluded_at IS NULL
 UNION ALL SELECT e.entry_type,e.slug,e.kind,CASE WHEN e.entry_type='PRACTICE' THEN e.definition->>'groupSlug' END,
 CASE WHEN e.entry_type='PRACTICE' THEN e.definition->'definition' ELSE e.definition END
 FROM catalog_entry e WHERE e.definition IS NOT NULL AND e.excluded_at IS NULL AND NOT EXISTS(SELECT 1 FROM _cutover_bundle b WHERE b.entry_type=e.entry_type AND b.slug=e.slug);
UPDATE practice p SET catalog_slug=o.slug,catalog_base=jsonb_build_object('kind',o.kind,'groupSlug',o.group_slug,'definition',o.definition)
 FROM _cutover_old_practice source JOIN _cutover_old_practice_catalog_installation i ON i.workspace_id=source.workspace_id AND i.provenance_linked_at IS NULL
 LEFT JOIN _cutover_old_practice_group g ON g.id=source.practice_group_id JOIN _cutover_offer o ON o.entry_type='PRACTICE' AND o.slug=source.slug AND g.slug IS NOT DISTINCT FROM o.group_slug
 WHERE p.id=source.id AND source.source_curated_slug IS NULL AND p.kind=o.kind
 AND pg_temp.cutover_columns(to_jsonb(source))=jsonb_set(o.definition,'{guidance,goingWell}','null'::jsonb);
UPDATE practice_group g SET catalog_slug=o.slug,catalog_base=o.definition
 FROM _cutover_old_practice_group source JOIN _cutover_old_practice_catalog_installation i ON i.workspace_id=source.workspace_id AND i.provenance_linked_at IS NULL
 JOIN _cutover_offer o ON o.entry_type='GROUP' AND o.slug=source.slug
 WHERE g.id=source.id AND source.source_curated_slug IS NULL AND o.definition=jsonb_build_object('name',source.name,'description',source.description,'icon',source.icon,'color',source.color);

CREATE TEMP TABLE _job_key_candidates(job_id uuid,workspace_id bigint,kind varchar(64),source_id bigint) ON COMMIT DROP;
INSERT INTO _job_key_candidates
 SELECT id,workspace_id,
 CASE WHEN metadata->>'subject_role'='REVIEWER' THEN 'scm.pull_request_review'
      ELSE COALESCE(artifact_kind,CASE job_type WHEN 'PULL_REQUEST_REVIEW' THEN 'scm.pull_request'
        WHEN 'ISSUE_REVIEW' THEN 'scm.issue' WHEN 'CONVERSATION_REVIEW' THEN 'chat.thread'
        WHEN 'DOCUMENT_REVIEW' THEN 'docs.document' END) END,
 CASE WHEN metadata->>'subject_role'='REVIEWER' THEN NULLIF(metadata->>'review_id','')::bigint
      ELSE COALESCE(NULLIF(metadata->>'pull_request_id','')::bigint,NULLIF(metadata->>'issue_id','')::bigint,
        NULLIF(metadata->>'slack_thread_id','')::bigint,NULLIF(metadata->>'docs_document_id','')::bigint) END
 FROM _cutover_old_agent_job;
INSERT INTO _job_key_candidates
 SELECT o.agent_job_id,o.workspace_id,
        CASE WHEN j.metadata->>'subject_role'='REVIEWER' THEN 'scm.pull_request_review' ELSE o.artifact_kind END,
        CASE WHEN j.metadata->>'subject_role'='REVIEWER' THEN NULLIF(j.metadata->>'review_id','')::bigint ELSE o.artifact_id END
 FROM _cutover_old_observation o JOIN _cutover_old_agent_job j ON j.id=o.agent_job_id;
INSERT INTO _job_key_candidates
 SELECT s.job_id,s.workspace_id,
        CASE WHEN s.signal_name='scm.pull_request.reviewed' THEN 'scm.pull_request_review' ELSE s.artifact_kind END,
        CASE WHEN s.signal_name='scm.pull_request.reviewed' THEN substring(s.revision FROM 7)::bigint ELSE s.artifact_id END
 FROM _cutover_old_artifact_signal s WHERE s.job_id IS NOT NULL;
INSERT INTO _job_key_candidates
 SELECT f.agent_job_id,f.workspace_id,
        CASE WHEN j.metadata->>'subject_role'='REVIEWER' THEN 'scm.pull_request_review' ELSE f.artifact_kind END,
        CASE WHEN j.metadata->>'subject_role'='REVIEWER' THEN NULLIF(j.metadata->>'review_id','')::bigint ELSE f.artifact_id END
 FROM _cutover_old_feedback f JOIN _cutover_old_agent_job j ON j.id=f.agent_job_id WHERE f.artifact_id IS NOT NULL;

UPDATE _job_key_candidates SET kind=pg_temp.cutover_kind(kind);
-- An exact reviewer event restores reviewer identity when the subject flag was stripped.
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _job_key_candidates c JOIN _job_key_candidates v ON v.job_id=c.job_id
           AND v.kind='scm.pull_request_review' AND v.source_id IS NOT NULL
           WHERE c.kind='scm.pull_request' AND c.source_id IS NOT NULL
           AND NOT EXISTS(SELECT 1 FROM pull_request_review p WHERE p.id=v.source_id AND p.pull_request_id=c.source_id)
           AND NOT EXISTS(SELECT 1 FROM _cutover_old_artifact_signal e WHERE e.job_id=c.job_id
             AND e.signal_name='scm.pull_request.reviewed' AND e.artifact_id=c.source_id
             AND e.revision='event~'||v.source_id::text)) THEN
   RAISE EXCEPTION 'reviewer parent differs from routed pull request'; END IF;
END $$;
UPDATE _job_key_candidates c SET kind='scm.pull_request_review',source_id=v.source_id
 FROM (SELECT job_id,min(source_id) AS source_id FROM _job_key_candidates
       WHERE kind='scm.pull_request_review' AND source_id IS NOT NULL GROUP BY job_id
       HAVING count(DISTINCT source_id)=1) v
 WHERE c.job_id=v.job_id AND c.kind='scm.pull_request';
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _job_key_candidates WHERE source_id IS NOT NULL GROUP BY job_id
           HAVING count(DISTINCT (workspace_id,kind,source_id))>1) THEN
   RAISE EXCEPTION 'job item keys disagree'; END IF;
 IF EXISTS(SELECT 1 FROM _job_key_candidates WHERE source_id<=0 OR (source_id IS NOT NULL AND kind IS NULL)) THEN
   RAISE EXCEPTION 'job has invalid routed item'; END IF;
END $$;
CREATE TEMP TABLE _job_work ON COMMIT DROP AS
 SELECT DISTINCT job_id,workspace_id,kind,source_id FROM _job_key_candidates WHERE source_id IS NOT NULL;
CREATE UNIQUE INDEX ON _job_work(job_id);
CREATE TEMP TABLE _discarded_job_ids ON COMMIT DROP AS
 SELECT j.id FROM _cutover_old_agent_job j WHERE NOT EXISTS(SELECT 1 FROM _job_work w WHERE w.job_id=j.id);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _discarded_job_ids d JOIN _cutover_old_agent_job j ON j.id=d.id
  WHERE (j.metadata IS NOT NULL AND j.metadata<>'{}'::jsonb)
   OR EXISTS(SELECT 1 FROM _cutover_old_observation o WHERE o.agent_job_id=d.id)
   OR EXISTS(SELECT 1 FROM _cutover_old_feedback f WHERE f.agent_job_id=d.id)
   OR EXISTS(SELECT 1 FROM _cutover_old_feedback_dispatch f WHERE f.agent_job_id=d.id)
   OR EXISTS(SELECT 1 FROM _cutover_old_public_review_completion p WHERE p.job_id=d.id)
   OR EXISTS(SELECT 1 FROM _cutover_old_review_composition_basis b WHERE b.job_id=d.id)) THEN
  RAISE EXCEPTION 'unresolved job has product facts or unredacted metadata'; END IF;
END $$;

CREATE TEMP TABLE _work_ref(workspace_id bigint,kind varchar(64),source_id bigint,
 PRIMARY KEY(workspace_id,kind,source_id)) ON COMMIT DROP;
INSERT INTO _work_ref
 SELECT workspace_id,kind,source_id FROM _job_work
 UNION SELECT workspace_id,pg_temp.cutover_kind(artifact_kind),artifact_id FROM _cutover_old_observation
 UNION SELECT workspace_id,pg_temp.cutover_kind(artifact_kind),artifact_id FROM _cutover_old_feedback WHERE artifact_id IS NOT NULL
 UNION SELECT workspace_id,pg_temp.cutover_kind(artifact_kind),artifact_id FROM _cutover_old_artifact_signal
 UNION SELECT workspace_id,pg_temp.cutover_kind(artifact_kind),cursor_artifact_id FROM _cutover_old_review_backfill_run WHERE cursor_artifact_id IS NOT NULL;
INSERT INTO _work_ref
 SELECT workspace_id,'scm.pull_request_review',substring(revision FROM 7)::bigint
 FROM _cutover_old_artifact_signal WHERE signal_name='scm.pull_request.reviewed'
 ON CONFLICT DO NOTHING;
-- Recover immutable ancestry from exact released references even when a provider mirror was removed.
CREATE TEMP TABLE _cutover_review_parent_candidate(workspace_id bigint,review_source_id bigint,parent_source_id bigint) ON COMMIT DROP;
INSERT INTO _cutover_review_parent_candidate
 SELECT x.workspace_id,x.source_id,p.pull_request_id FROM _work_ref x
 JOIN pull_request_review p ON x.kind='scm.pull_request_review' AND p.id=x.source_id
 WHERE p.pull_request_id IS NOT NULL
 UNION ALL SELECT s.workspace_id,substring(s.revision FROM 7)::bigint,s.artifact_id
 FROM _cutover_old_artifact_signal s WHERE s.signal_name='scm.pull_request.reviewed' AND s.artifact_kind='scm.pull_request'
 UNION ALL SELECT w.workspace_id,w.source_id,NULLIF(j.metadata->>'pull_request_id','')::bigint
 FROM _job_work w JOIN _cutover_old_agent_job j ON j.id=w.job_id
 WHERE w.kind='scm.pull_request_review' AND NULLIF(j.metadata->>'pull_request_id','') IS NOT NULL
 UNION ALL SELECT w.workspace_id,w.source_id,o.artifact_id
 FROM _job_work w JOIN _cutover_old_observation o ON o.agent_job_id=w.job_id AND o.workspace_id=w.workspace_id
 WHERE w.kind='scm.pull_request_review' AND o.artifact_kind='scm.pull_request'
 UNION ALL SELECT w.workspace_id,w.source_id,f.artifact_id
 FROM _job_work w JOIN _cutover_old_feedback f ON f.agent_job_id=w.job_id AND f.workspace_id=w.workspace_id
 WHERE w.kind='scm.pull_request_review' AND f.artifact_kind='scm.pull_request' AND f.artifact_id IS NOT NULL;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_review_parent_candidate GROUP BY workspace_id,review_source_id
           HAVING count(DISTINCT parent_source_id)>1)
 OR EXISTS(SELECT 1 FROM _cutover_review_parent_candidate WHERE parent_source_id<=0 OR review_source_id<=0) THEN
   RAISE EXCEPTION 'exact reviewer ancestry disagrees'; END IF;
END $$;
CREATE TEMP TABLE _cutover_review_parent ON COMMIT DROP AS
 SELECT DISTINCT workspace_id,review_source_id,parent_source_id FROM _cutover_review_parent_candidate;
CREATE UNIQUE INDEX ON _cutover_review_parent(workspace_id,review_source_id);
INSERT INTO _work_ref
 SELECT workspace_id,'scm.pull_request',parent_source_id FROM _cutover_review_parent ON CONFLICT DO NOTHING;
-- Parent repositories for all PR/issue items, including shared provider rows.
INSERT INTO _work_ref
 SELECT x.workspace_id,'scm.repository',i.repository_id FROM _work_ref x JOIN issue i ON i.id=x.source_id
 WHERE x.kind IN ('scm.pull_request','scm.issue') AND i.repository_id IS NOT NULL ON CONFLICT DO NOTHING;
-- Adapter-owned workspace tables already have exact tenancy.
INSERT INTO _work_ref SELECT workspace_id,'chat.thread',id FROM slack_thread ON CONFLICT DO NOTHING;
INSERT INTO _work_ref SELECT workspace_id,'docs.document',id FROM outline_document ON CONFLICT DO NOTHING;

CREATE TEMP TABLE _cutover_monitor ON COMMIT DROP AS
 SELECT DISTINCT m.workspace_id,m.id AS monitor_id,r.id AS repository_id FROM repository_to_monitor m
 JOIN workspace w ON w.id=m.workspace_id LEFT JOIN organization o ON o.id=w.organization_id
 JOIN identity_provider p ON p.id=o.provider_id OR (o.id IS NULL AND EXISTS(
  SELECT 1 FROM connection c WHERE c.workspace_id=w.id AND c.kind IN ('GITHUB','GITLAB') AND c.kind=p.type
   AND rtrim(COALESCE(c.config->>'serverUrl',CASE c.kind WHEN 'GITHUB' THEN 'https://github.com' ELSE 'https://gitlab.com' END),'/')=rtrim(p.server_url,'/')))
 JOIN repository r ON r.provider_id=p.id AND ((m.native_id IS NOT NULL AND r.native_id=m.native_id) OR (m.native_id IS NULL AND r.name_with_owner=m.name_with_owner));
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_monitor GROUP BY monitor_id HAVING count(*)>1) THEN RAISE EXCEPTION 'monitor provider/source is ambiguous'; END IF;
 IF EXISTS(SELECT 1 FROM _work_ref WHERE kind NOT IN ('scm.repository','scm.pull_request','scm.issue','scm.pull_request_review','chat.thread','docs.document')) THEN RAISE EXCEPTION 'unknown released item kind'; END IF;
 IF EXISTS(SELECT 1 FROM _work_ref x JOIN issue i ON i.id=x.source_id WHERE (x.kind='scm.pull_request' AND i.issue_type<>'PULL_REQUEST') OR (x.kind='scm.issue' AND i.issue_type<>'ISSUE')) THEN RAISE EXCEPTION 'item kind disagrees with provider mirror'; END IF;
 IF EXISTS(SELECT 1 FROM _work_ref x JOIN slack_thread t ON x.kind='chat.thread' AND t.id=x.source_id WHERE x.workspace_id<>t.workspace_id) OR EXISTS(SELECT 1 FROM _work_ref x JOIN outline_document d ON x.kind='docs.document' AND d.id=x.source_id WHERE x.workspace_id<>d.workspace_id) THEN RAISE EXCEPTION 'source crosses workspace'; END IF;
END $$;
INSERT INTO _work_ref SELECT workspace_id,'scm.repository',repository_id FROM _cutover_monitor ON CONFLICT DO NOTHING;
INSERT INTO item(workspace_id,kind,source_id,created_at,removed_at)
 SELECT x.workspace_id,x.kind,x.source_id,COALESCE(r.created_at,c.at),
        CASE WHEN r.id IS NULL THEN c.at END
 FROM _work_ref x LEFT JOIN repository r ON r.id=x.source_id
 CROSS JOIN _cutover_clock c WHERE x.kind='scm.repository';
INSERT INTO item(workspace_id,kind,source_id,parent_id,created_at,removed_at)
 SELECT x.workspace_id,x.kind,x.source_id,p.id,COALESCE(i.created_at,c.at),
        COALESCE(i.deleted_at,CASE WHEN i.id IS NULL THEN c.at END)
 FROM _work_ref x LEFT JOIN issue i ON i.id=x.source_id
 LEFT JOIN item p ON p.workspace_id=x.workspace_id AND p.kind='scm.repository' AND p.source_id=i.repository_id
 CROSS JOIN _cutover_clock c WHERE x.kind IN ('scm.pull_request','scm.issue');
INSERT INTO item(workspace_id,kind,source_id,parent_id,created_at,removed_at)
 SELECT x.workspace_id,x.kind,x.source_id,p.id,COALESCE(r.submitted_at,c.at),CASE WHEN r.id IS NULL THEN c.at END
 FROM _work_ref x LEFT JOIN pull_request_review r ON r.id=x.source_id
 LEFT JOIN _cutover_review_parent ancestry ON ancestry.workspace_id=x.workspace_id AND ancestry.review_source_id=x.source_id
 LEFT JOIN item p ON p.workspace_id=x.workspace_id AND p.kind='scm.pull_request' AND p.source_id=ancestry.parent_source_id
 CROSS JOIN _cutover_clock c WHERE x.kind='scm.pull_request_review';
INSERT INTO item(workspace_id,kind,source_id,created_at,removed_at)
 SELECT x.workspace_id,x.kind,x.source_id,COALESCE(t.created_at,c.at),CASE WHEN t.id IS NULL THEN c.at END
 FROM _work_ref x LEFT JOIN slack_thread t ON t.id=x.source_id CROSS JOIN _cutover_clock c WHERE x.kind='chat.thread';
INSERT INTO item(workspace_id,kind,source_id,created_at,removed_at)
 SELECT x.workspace_id,x.kind,x.source_id,COALESCE(d.created_at,c.at),
        COALESCE(d.deleted_at,CASE WHEN d.id IS NULL THEN c.at END)
 FROM _work_ref x LEFT JOIN outline_document d ON d.id=x.source_id CROSS JOIN _cutover_clock c WHERE x.kind='docs.document';
CREATE TEMP TABLE _item_map ON COMMIT DROP AS SELECT workspace_id,kind,source_id,id AS item_id FROM item
 UNION ALL SELECT workspace_id,'chat.conversation_thread',source_id,id FROM item WHERE kind='chat.thread';
CREATE UNIQUE INDEX ON _item_map(workspace_id,kind,source_id);
CREATE TEMP TABLE _cutover_person ON COMMIT DROP AS SELECT user_id,account_id FROM _person_map;
ALTER TABLE _cutover_person ADD PRIMARY KEY(user_id);
CREATE TEMP TABLE _cutover_item ON COMMIT DROP AS
 SELECT workspace_id,kind AS old_kind,source_id AS old_source_id,item_id FROM _item_map;
ALTER TABLE _cutover_item ADD PRIMARY KEY(workspace_id,old_kind,old_source_id);

INSERT INTO review_scope_repository(workspace_id,repository_monitor_id,base_branches)
 SELECT workspace_id,repository_monitor_id,base_branches FROM _cutover_old_practice_review_repository_target;
INSERT INTO review_schedule(id,version,workspace_id,kind,cadence,lookback_days,enabled,next_run_at,last_run_at,created_by_account_id,created_at,updated_at)
 SELECT id,version,workspace_id,pg_temp.cutover_kind(artifact_kind),cadence,lookback_days,enabled,next_run_at,last_run_at,created_by_account_id,created_at,updated_at FROM _cutover_old_review_sweep_schedule;
INSERT INTO review_batch(id,version,workspace_id,kind,origin,schedule_id,from_at,to_at,status,pause_reason,estimated_items,estimated_cost_usd,cursor_item_id,submitted_count,skipped_count,failed_count,requested_by_account_id,confirmed_by_account_id,created_at,started_at,finished_at,updated_at)
 SELECT b.id,b.version,b.workspace_id,pg_temp.cutover_kind(b.artifact_kind),CASE b.discovered_via WHEN 'SWEEP' THEN 'SCHEDULE' ELSE 'BACKFILL' END,b.sweep_schedule_id,b.from_at,b.to_at,b.status,b.pause_reason,b.estimated_artifacts,b.estimated_cost_usd,i.item_id,b.submitted_count,b.passed_count,b.failed_count,b.requested_by_account_id,b.confirmed_by_account_id,b.created_at,b.started_at,b.finished_at,b.updated_at
 FROM _cutover_old_review_backfill_run b LEFT JOIN _cutover_item i ON (i.workspace_id,i.old_kind,i.old_source_id)=(b.workspace_id,b.artifact_kind,b.cursor_artifact_id);

INSERT INTO item_event(id,workspace_id,item_id,name,item_version,occurred_at,found_by,
 actor_user_id,requested_by_id,state,reason,decided_at,last_attempted_at,retry_at)
SELECT s.id,s.workspace_id,m.item_id,
 CASE WHEN s.signal_name='scm.pull_request.reviewed' THEN 'scm.pull_request_review.submitted'
 ELSE regexp_replace(s.signal_name,'^chat\.conversation_thread\.','chat.thread.') END,
 s.revision,s.occurred_at,
 CASE s.discovered_via WHEN 'EVENT' THEN 'WEBHOOK' WHEN 'SYNC' THEN 'SYNC'
      WHEN 'MANUAL' THEN 'REQUEST' WHEN 'BACKFILL' THEN 'BACKFILL' WHEN 'SWEEP' THEN 'SCHEDULE' END,
 s.actor_user_id,p.account_id,
 CASE s.state WHEN 'RECORDED' THEN 'RECORDED' WHEN 'DEFERRED' THEN 'WAITING'
      WHEN 'TRIGGERED' THEN 'STARTED' WHEN 'SUPPRESSED' THEN 'WITHHELD'
      WHEN 'PENDING' THEN 'BLOCKED' WHEN 'LAPSED' THEN 'EXPIRED' END,
 CASE s.state_reason WHEN 'GATE_SKIPPED' THEN 'GATE_WITHHELD' WHEN 'PRACTICE_AUTONOMY_OFF' THEN 'FEEDBACK_MODE_OFF'
      WHEN 'ARTIFACT_NOT_VISIBLE' THEN 'ITEM_NOT_VISIBLE' WHEN 'ARTIFACT_GONE' THEN 'ITEM_GONE' ELSE s.state_reason END,
 s.state_changed_at,s.last_attempted_at,
 CASE WHEN s.state IN ('RECORDED','DEFERRED','PENDING') THEN c.at END
FROM _cutover_old_artifact_signal s
JOIN _item_map m ON m.workspace_id=s.workspace_id
 AND m.kind=CASE WHEN s.signal_name='scm.pull_request.reviewed' THEN 'scm.pull_request_review' ELSE s.artifact_kind END
 AND m.source_id=CASE WHEN s.signal_name='scm.pull_request.reviewed' THEN substring(s.revision FROM 7)::bigint ELSE s.artifact_id END
LEFT JOIN _person_map p ON p.user_id=s.requested_by_user_id CROSS JOIN _cutover_clock c;

CREATE TEMP TABLE _job_transition ON COMMIT DROP AS
WITH origins AS (
 SELECT j.id,CASE
   WHEN EXISTS(SELECT 1 FROM _cutover_old_observation o WHERE o.agent_job_id=j.id AND o.origin='BACKFILL')
     OR j.metadata->>'observation_origin'='BACKFILL'
     THEN CASE WHEN EXISTS(SELECT 1 FROM _cutover_old_artifact_signal s WHERE s.job_id=j.id AND s.discovered_via='SWEEP')
               THEN 'SCHEDULE' ELSE 'BACKFILL' END
   WHEN EXISTS(SELECT 1 FROM _cutover_old_observation o WHERE o.agent_job_id=j.id AND o.origin='MANUAL')
     OR j.metadata->>'observation_origin'='MANUAL' THEN 'REQUEST'
   WHEN EXISTS(SELECT 1 FROM _cutover_old_observation o WHERE o.agent_job_id=j.id AND o.origin='LIVE') THEN 'EVENT'
   WHEN EXISTS(SELECT 1 FROM _cutover_old_artifact_signal s WHERE s.job_id=j.id AND s.discovered_via='SWEEP') THEN 'SCHEDULE'
   WHEN EXISTS(SELECT 1 FROM _cutover_old_artifact_signal s WHERE s.job_id=j.id AND s.discovered_via='BACKFILL') THEN 'BACKFILL'
   WHEN EXISTS(SELECT 1 FROM _cutover_old_artifact_signal s WHERE s.job_id=j.id AND s.discovered_via='MANUAL')
     OR j.practice_trigger_mode='MANUAL' THEN 'REQUEST' ELSE 'EVENT' END AS origin
 FROM _cutover_old_agent_job j
), admission AS (
 SELECT agent_job_id,min(observed_at) AS admitted_at FROM _cutover_old_observation GROUP BY agent_job_id
)
SELECT j.id,j.workspace_id,m.item_id,w.kind AS item_kind,o.origin,
 a.admitted_at,
 CASE WHEN o.origin<>'BACKFILL' AND o.origin<>'SCHEDULE'
  AND j.job_type='PULL_REQUEST_REVIEW'
  AND (j.metadata->'subject_role' IS NULL OR j.metadata->>'subject_role'='AUTHOR')
  AND jsonb_typeof(j.metadata->'current_work_at_admission')='boolean'
  AND j.metadata->>'current_work_at_admission'='true'
  AND (j.metadata->>'signal' IN ('scm.pull_request.opened','scm.pull_request.ready',
       'scm.pull_request.synchronized','scm.pull_request.edited','scm.pull_request.manual_review')
       OR (j.metadata->'signal' IS NULL AND j.metadata->>'observation_origin'='MANUAL'))
  AND j.evidence_snapshot->'reviewedWork'->>'retainedBasis'='ADMISSION'
  THEN j.created_at ELSE COALESCE(a.admitted_at,j.completed_at,j.created_at) END AS ordered_at,
 CASE WHEN w.kind='scm.pull_request_review' THEN
      COALESCE(NULLIF(j.evidence_snapshot->'reviewedWork'->>'head',''),NULLIF(j.metadata->>'commit_sha',''),pr.commit_id)
      ELSE COALESCE(NULLIF(j.evidence_snapshot->'reviewedWork'->>'head',''),NULLIF(j.metadata->>'commit_sha',''),
        NULLIF(j.evidence_snapshot->'reviewedWork'->>'titleAndDescriptionRevision',''),
        NULLIF(j.metadata->>'review_snapshot_id',''),NULLIF(j.metadata->>'slack_last_ts','')) END AS captured_head,
 NULLIF(j.metadata->>'base_ref_oid','') AS base_version,
 (SELECT e.id FROM _cutover_old_artifact_signal s JOIN item_event e ON e.id=s.id
  WHERE s.job_id=j.id AND s.workspace_id=j.workspace_id
  ORDER BY CASE WHEN s.signal_name=j.metadata->>'signal' AND s.revision=j.metadata->>'signal_revision'
                THEN 0 ELSE 1 END,s.state_changed_at DESC,s.id LIMIT 1) AS event_candidate,
 (SELECT p.account_id FROM _cutover_old_artifact_signal s JOIN _person_map p ON p.user_id=s.requested_by_user_id
  WHERE s.job_id=j.id AND s.workspace_id=j.workspace_id ORDER BY s.state_changed_at DESC,s.id LIMIT 1) AS requested_by_id
FROM _cutover_old_agent_job j JOIN _job_work w ON w.job_id=j.id
JOIN _item_map m ON (m.workspace_id,m.kind,m.source_id)=(w.workspace_id,w.kind,w.source_id)
JOIN origins o ON o.id=j.id LEFT JOIN admission a ON a.agent_job_id=j.id
LEFT JOIN pull_request_review pr ON w.kind='scm.pull_request_review' AND pr.id=w.source_id;
CREATE UNIQUE INDEX ON _job_transition(id);

INSERT INTO review(id,workspace_id,item_id,kind,item_version,base_version,origin,event_id,batch_id,
 requested_by_id,status,stop_reason,budget_usd,rollout_revision,ordered_at,created_at,admitted_at,completed_at,public_review_at)
SELECT j.id,j.workspace_id,t.item_id,'ITEM',
 CASE WHEN t.item_kind='scm.pull_request' AND t.base_version IS NOT NULL AND t.captured_head IS NOT NULL
      THEN 'base~'||t.base_version||'~head~'||t.captured_head ELSE t.captured_head END,
 t.base_version,t.origin,CASE WHEN t.origin='EVENT' THEN t.event_candidate END,NULL,
 CASE WHEN t.origin='REQUEST' THEN t.requested_by_id END,
 CASE WHEN j.status IN ('QUEUED','RUNNING') THEN CASE WHEN t.admitted_at IS NOT NULL THEN 'PARTIAL' ELSE 'CANCELLED' END WHEN j.status='COMPLETED' AND j.delivery_status='FAILED' THEN 'FAILED'
      WHEN j.status='COMPLETED' THEN 'COMPLETE' WHEN j.status='CANCELLED' THEN 'CANCELLED'
      WHEN j.status IN ('FAILED','TIMED_OUT') THEN 'FAILED' ELSE j.status END,
 CASE WHEN j.status IN ('QUEUED','RUNNING') THEN 'CONTRACT_CHANGED' WHEN j.status='TIMED_OUT' THEN 'TIMED_OUT'
      WHEN j.status='FAILED' THEN 'EXECUTION_FAILED'
      WHEN j.status='COMPLETED' AND j.delivery_status='FAILED' THEN 'PROCESSING_FAILED'
      WHEN j.status='CANCELLED' THEN CASE j.cancellation_reason
        WHEN 'PERSON_DATA_ERASED' THEN 'PERSON_DATA_ERASED'
        WHEN 'STALE_ROLLOUT_REVISION' THEN 'STALE_ROLLOUT_REVISION'
        WHEN 'REPLACED' THEN 'REPLACED' ELSE 'LEGACY_FAILURE' END END,
 NULL,j.practice_rollout_revision,t.ordered_at,j.created_at,t.admitted_at,CASE WHEN j.status IN ('QUEUED','RUNNING') THEN c.at ELSE j.completed_at END,p.accepted_at
FROM _cutover_old_agent_job j JOIN _job_transition t ON t.id=j.id
LEFT JOIN _cutover_old_public_review_completion p ON p.job_id=j.id AND p.workspace_id=j.workspace_id CROSS JOIN _cutover_clock c;

INSERT INTO review_job(id,review_id,workspace_id,submitted_at,status,attempt,processing_status,available_at,hold_reason,worker_id,
 idempotency_key,trace_id,input,config_snapshot,capture,output,exit_code,error_message,cancellation_reason,
 conversation_prepared_at,practice_page_prepared_at,public_review_digest,admission_attempt,admission_digest,
 llm_calls,llm_input_tokens,llm_output_tokens,llm_reasoning_tokens,llm_cache_read_tokens,llm_cache_write_tokens,
 started_at,execution_started_at,completed_at)
SELECT j.id,j.id,j.workspace_id,j.created_at,CASE WHEN j.status IN ('QUEUED','RUNNING') THEN 'CANCELLED' ELSE j.status END,j.retry_count,
 CASE WHEN j.status IN ('QUEUED','RUNNING') THEN 'DONE' ELSE CASE j.delivery_status WHEN 'PENDING' THEN 'FAILED' WHEN 'DELIVERED' THEN 'DONE' WHEN 'FAILED' THEN 'FAILED' ELSE 'NONE' END END,
 j.available_at,j.hold_reason,CASE WHEN j.status IN ('QUEUED','RUNNING') THEN NULL ELSE j.worker_id END,j.idempotency_key,j.trace_id,jsonb_build_object('reviewId',j.id,'itemId',r.item_id::text),j.config_snapshot,
 j.evidence_snapshot-'reviewedWork'-'practices'-'answeredPractices',j.output,j.exit_code,j.error_message,CASE WHEN j.status IN ('QUEUED','RUNNING') THEN 'CONTRACT_CHANGED' ELSE CASE WHEN j.cancellation_reason IN('DRAIN_GRACEFUL','DRAIN_IMMEDIATE','BUDGET_EXHAUSTED','MODEL_UNAVAILABLE','MEMBER_AI_DECLINED','PERSON_DATA_ERASED','CANCELLED_BY_ADMIN','CANCELLED_BY_REQUESTER','CONTRACT_CHANGED') THEN j.cancellation_reason END END,
 j.in_chat_prepared_at,j.in_app_prepared_at,p.review_digest,
 COALESCE(p.admission_attempt,NULLIF(j.metadata->>'observation_admission_attempt','')::integer),
 COALESCE(p.admission_digest,NULLIF(j.metadata->>'observation_admission_digest','')),
 COALESCE(j.llm_total_calls,0),COALESCE(j.llm_total_input_tokens,0),COALESCE(j.llm_total_output_tokens,0),
 COALESCE(j.llm_total_reasoning_tokens,0),COALESCE(j.llm_cache_read_tokens,0),COALESCE(j.llm_cache_write_tokens,0),
 j.started_at,j.execution_started_at,CASE WHEN j.status IN ('QUEUED','RUNNING') THEN c.at ELSE j.completed_at END
FROM _cutover_old_agent_job j JOIN review r ON r.id=j.id
LEFT JOIN _cutover_old_public_review_completion p ON p.job_id=j.id AND p.workspace_id=j.workspace_id CROSS JOIN _cutover_clock c;


UPDATE review r SET checks=jsonb_build_object('MIGRATION',jsonb_build_object(
 'jobStatus',j.status,'processingStatus',j.delivery_status,'triggerMode',j.practice_trigger_mode,
 'cancellationReason',j.cancellation_reason,'deliveryAttempts',j.delivery_attempts)) FROM _cutover_old_agent_job j WHERE j.id=r.id;
INSERT INTO review_composition_basis(job_id,workspace_id,admission_attempt,admission_digest,basis_digest,basis_version,copy_id,expires_at,payload)
SELECT job_id,workspace_id,admission_attempt,admission_digest,basis_digest,basis_version,copy_id,expires_at,payload FROM _cutover_old_review_composition_basis;
ALTER TABLE llm_usage_event ADD COLUMN review_id uuid,ADD COLUMN search_units bigint NOT NULL DEFAULT 0,ADD COLUMN unreported_calls integer NOT NULL DEFAULT 0;
ALTER TABLE llm_usage_event DROP CONSTRAINT ck_llm_usage_event_source_type;
ALTER TABLE llm_usage_event ALTER COLUMN source_type TYPE varchar(32);
UPDATE llm_usage_event e SET review_id=j.review_id FROM review_job j WHERE e.source_type='AGENT_JOB' AND e.source_id=j.id AND e.workspace_id=j.workspace_id;
UPDATE llm_usage_event SET source_type='REVIEW_JOB' WHERE source_type='AGENT_JOB';
ALTER TABLE llm_usage_event ADD CONSTRAINT ck_llm_usage_event_source_type CHECK(source_type IN ('REVIEW_JOB','MENTOR_TURN','PRACTICE_SCRIPT_DECISION','PRACTICE_SCRIPT_EMBEDDING','PRACTICE_SCRIPT_RERANKING'));
ALTER TABLE llm_usage_event ADD CONSTRAINT uk_llm_usage_event_workspace UNIQUE(id,workspace_id);
ALTER TABLE llm_usage_event ADD CONSTRAINT sfk_llm_usage_event_review FOREIGN KEY(review_id,workspace_id) REFERENCES review(id,workspace_id) ON DELETE SET NULL(review_id);
ALTER TABLE llm_usage_event ADD CONSTRAINT ck_llm_usage_event_counts CHECK(search_units>=0 AND unreported_calls>=0);
ALTER TABLE person_evidence_copy ADD COLUMN created_at timestamptz;
UPDATE person_evidence_copy e SET created_at=COALESCE(j.created_at,c.at) FROM _cutover_clock c LEFT JOIN _cutover_old_agent_job j ON true WHERE e.job_id=j.id;
UPDATE person_evidence_copy SET created_at=(SELECT at FROM _cutover_clock) WHERE created_at IS NULL;
ALTER TABLE person_evidence_copy ALTER COLUMN created_at SET NOT NULL,ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE person_evidence_copy ADD CONSTRAINT uk_person_evidence_copy_workspace UNIQUE(id,workspace_id);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_old_observation GROUP BY agent_job_id,practice_id HAVING count(DISTINCT practice_revision_id)>1 OR (count(practice_revision_id)>0 AND count(practice_revision_id)<count(*))) THEN RAISE EXCEPTION 'result/capture version is ambiguous'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_agent_job j CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(j.evidence_snapshot->'practices')='array' THEN j.evidence_snapshot->'practices' ELSE '[]'::jsonb END) e WHERE NOT EXISTS(SELECT 1 FROM practice p WHERE p.workspace_id=j.workspace_id AND p.slug=e->>'slug')) THEN RAISE EXCEPTION 'captured practice does not exist in workspace'; END IF;
END $$;
INSERT INTO review_practice(review_id,practice_id,workspace_id,practice_version_id,status,items_listed,listing_complete)
 SELECT o.agent_job_id,o.practice_id,o.workspace_id,min(o.practice_revision_id),'DONE',1,true
 FROM _cutover_old_observation o GROUP BY o.agent_job_id,o.practice_id,o.workspace_id;

CREATE TEMP TABLE _captured_practice ON COMMIT DROP AS
 SELECT j.id AS review_id,j.workspace_id,p.id AS practice_id,
        NULLIF(e.value->>'revisionId','')::bigint AS version_id
 FROM _cutover_old_agent_job j CROSS JOIN LATERAL jsonb_array_elements(
   CASE WHEN jsonb_typeof(j.evidence_snapshot->'practices')='array'
        THEN j.evidence_snapshot->'practices' ELSE '[]'::jsonb END) e(value)
 JOIN practice p ON p.workspace_id=j.workspace_id AND p.slug=e.value->>'slug';
CREATE TEMP TABLE _capture_decision ON COMMIT DROP AS
 SELECT j.id AS review_id,j.workspace_id,p.id AS practice_id,d.value AS decision
 FROM _cutover_old_agent_job j CROSS JOIN LATERAL jsonb_array_elements(
   CASE WHEN jsonb_typeof(j.review_readiness->'decisions')='array'
        THEN j.review_readiness->'decisions' ELSE '[]'::jsonb END) d(value)
 JOIN practice p ON p.workspace_id=j.workspace_id AND p.slug=d.value->>'practiceSlug';

INSERT INTO review_practice(review_id,practice_id,workspace_id,practice_version_id,status,reason,
 items_listed,listing_complete,capture_decision)
 SELECT k.review_id,k.practice_id,k.workspace_id,c.version_id,
 CASE WHEN d.decision->>'ready'='false' THEN 'WITHHELD'
      WHEN j.status IN ('FAILED','TIMED_OUT','CANCELLED') THEN 'FAILED' ELSE 'WITHHELD' END,
 CASE WHEN d.decision->>'ready'='false' THEN 'READINESS_REFUSED'
      WHEN j.status IN ('FAILED','TIMED_OUT','CANCELLED') THEN 'EXECUTION_FAILED' ELSE 'NO_RECORDED_RESULT' END,
 1,CASE WHEN j.evidence_snapshot->'manifest' IS NOT NULL THEN true ELSE NULL END,d.decision
 FROM (SELECT review_id,workspace_id,practice_id FROM _captured_practice
       UNION SELECT review_id,workspace_id,practice_id FROM _capture_decision) k
 JOIN _cutover_old_agent_job j ON j.id=k.review_id JOIN review r ON r.id=k.review_id
 LEFT JOIN _captured_practice c ON (c.review_id,c.workspace_id,c.practice_id)=(k.review_id,k.workspace_id,k.practice_id)
 LEFT JOIN _capture_decision d ON (d.review_id,d.workspace_id,d.practice_id)=(k.review_id,k.workspace_id,k.practice_id)
 ON CONFLICT(review_id,practice_id) DO UPDATE SET capture_decision=EXCLUDED.capture_decision;
INSERT INTO result(id,workspace_id,review_id,practice_id,practice_version_id,item_id,item_version,developer_id,
 outcome,severity,summary,explanation,evidence,evidence_version,recorded_at,ended_at,end_reason)
SELECT o.id,o.workspace_id,o.agent_job_id,o.practice_id,o.practice_revision_id,
 CASE WHEN t.item_kind='scm.pull_request_review' THEN t.item_id ELSE m.item_id END,
 r.item_version,p.account_id,
 CASE o.outcome WHEN 'NOT_APPLICABLE' THEN 'DOES_NOT_APPLY' WHEN 'UNDETERMINED' THEN 'COULD_NOT_DETERMINE' ELSE o.outcome END,
 CASE o.severity WHEN 'INFO' THEN 'TRIVIAL' ELSE o.severity END,
 o.summary,o.evidence_rationale,
 CASE WHEN jsonb_typeof(o.evidence->'undecidability')='object' THEN
      (o.evidence-'undecidability')||jsonb_build_object('openQuestions',jsonb_build_array(o.evidence->'undecidability'))
      WHEN jsonb_typeof(o.evidence->'undecidability')='array' THEN
      (o.evidence-'undecidability')||jsonb_build_object('openQuestions',o.evidence->'undecidability')
      ELSE CASE WHEN jsonb_exists(o.evidence, 'undecidability') THEN (o.evidence-'undecidability')||jsonb_build_object('openQuestions',o.evidence->'undecidability') ELSE o.evidence END END,
 0,o.observed_at,
 CASE WHEN o.superseded_at IS NOT NULL THEN greatest(o.superseded_at,o.observed_at) END,
 CASE WHEN o.superseded_at IS NOT NULL THEN 'WORK_CHANGED' END
FROM _cutover_old_observation o JOIN review r ON r.id=o.agent_job_id
JOIN _job_transition t ON t.id=o.agent_job_id
JOIN _item_map m ON (m.workspace_id,m.kind,m.source_id)=(o.workspace_id,o.artifact_kind,o.artifact_id)
JOIN _person_map p ON p.user_id=o.about_user_id;

INSERT INTO problem(id,workspace_id,result_id,position,key,severity,summary,explanation,citations,basis)
SELECT gen_random_uuid(),o.workspace_id,o.id,0,NULL,
 CASE o.severity WHEN 'INFO' THEN 'TRIVIAL' ELSE o.severity END,
 o.summary,COALESCE(o.evidence_rationale,o.summary),
 CASE WHEN jsonb_typeof(o.evidence->'citations')='array' THEN o.evidence->'citations' ELSE '[]'::jsonb END,NULL
FROM _cutover_old_observation o WHERE o.outcome='NOT_MET';

INSERT INTO result_mark(id,workspace_id,result_id,kind,reason,created_by_id,created_at,removed_by_id,removed_at,removal_reason)
SELECT id,workspace_id,observation_id,'INCORRECT',reason,invalidated_by_account_id,invalidated_at,
 restored_by_account_id,restored_at,restoration_reason FROM _cutover_old_observation_invalidation;

INSERT INTO review_item(workspace_id,review_id,practice_id,item_id,item_version,state,result_id,job_id,attempted_at)
 SELECT workspace_id,review_id,practice_id,item_id,item_version,'JUDGED',id,review_id,recorded_at FROM result;
INSERT INTO review_item(workspace_id,review_id,practice_id,item_id,item_version,state,job_id,attempted_at,reason,detail)
 SELECT p.workspace_id,p.review_id,p.practice_id,r.item_id,r.item_version,'WITHHELD',j.id,j.started_at,
        COALESCE(p.reason,'NO_RECORDED_RESULT'),CASE WHEN octet_length(p.capture_decision::text)<=8192 THEN p.capture_decision END
 FROM review_practice p JOIN review r ON r.id=p.review_id JOIN review_job j ON j.review_id=r.id
 WHERE NOT EXISTS(SELECT 1 FROM review_item a WHERE a.review_id=p.review_id AND a.practice_id=p.practice_id);

CREATE FUNCTION pg_temp.cutover_citations(v jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE out_value jsonb; k text; child jsonb; proof jsonb;
BEGIN
 IF v IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(v)='array' THEN
  SELECT COALESCE(jsonb_agg(pg_temp.cutover_citations(e.value) ORDER BY e.ordinal),'[]'::jsonb)
   INTO out_value FROM jsonb_array_elements(v) WITH ORDINALITY e(value,ordinal);
  RETURN out_value;
 END IF;
 IF jsonb_typeof(v)<>'object' THEN RETURN v; END IF;
 out_value := '{}'::jsonb;
 FOR k,child IN SELECT key,value FROM jsonb_each(v) LOOP
  out_value := out_value || jsonb_build_object(k,pg_temp.cutover_citations(child));
 END LOOP;
 IF out_value ? 'sourceKind' AND out_value ? 'artifactPath' THEN
  IF out_value ? 'sourcePath' AND out_value->'sourcePath' IS DISTINCT FROM out_value->'artifactPath' THEN
   RAISE EXCEPTION 'legacy citation paths conflict'; END IF;
  out_value := (out_value-'artifactPath')||jsonb_build_object('sourcePath',out_value->'artifactPath');
  IF jsonb_typeof(out_value->'verification')='object' THEN
   proof := out_value->'verification';
   proof := proof-'jobId'-'attempt'-'scope'-'citationSha256';
   out_value := jsonb_set(out_value,'{verification}',proof);
  END IF;
 END IF;
 RETURN out_value;
END $$;
UPDATE result SET evidence=pg_temp.cutover_citations(evidence),example=pg_temp.cutover_citations(example);
UPDATE problem SET citations=pg_temp.cutover_citations(citations);
UPDATE result SET evidence=jsonb_set(evidence,'{inapplicability}',
 ((evidence->'inapplicability')-'subject')||jsonb_build_object('prerequisite',evidence->'inapplicability'->'subject'))
 WHERE jsonb_typeof(evidence->'inapplicability')='object' AND jsonb_exists(evidence->'inapplicability', 'subject');

UPDATE review r SET status='PARTIAL',stop_reason=CASE
 WHEN EXISTS(SELECT 1 FROM review_item a WHERE a.review_id=r.id AND a.state='WITHHELD')
 THEN 'RESULT_WITHHELD' ELSE 'LEGACY_SCOPE_UNKNOWN' END
 WHERE r.status='COMPLETE' AND (
  EXISTS(SELECT 1 FROM review_item a WHERE a.review_id=r.id AND a.state IN ('LISTED','WITHHELD'))
  OR NOT EXISTS(SELECT 1 FROM review_item a WHERE a.review_id=r.id));

CREATE TEMP TABLE _cutover_result ON COMMIT DROP AS SELECT r.id AS observation_id,r.id AS result_id,p.id AS problem_id,r.workspace_id,r.developer_id FROM result r LEFT JOIN problem p ON p.result_id=r.id;
ALTER TABLE _cutover_result ADD PRIMARY KEY(observation_id);
CREATE TEMP TABLE _cutover_review ON COMMIT DROP AS
SELECT r.id AS job_id,r.id AS review_id,r.workspace_id,r.item_id,
 COALESCE((SELECT m.account_id FROM _cutover_person m JOIN _cutover_old_agent_job j ON j.id=r.id WHERE j.metadata->>'about_user_id'=m.user_id::text),
 (SELECT min(x.developer_id) FROM result x WHERE x.review_id=r.id HAVING count(DISTINCT x.developer_id)=1)) AS developer_id FROM review r;
ALTER TABLE _cutover_review ADD PRIMARY KEY(job_id);
UPDATE result SET evidence=evidence-'citations' WHERE outcome='NOT_MET';
CREATE TEMP TABLE _claim_rank ON COMMIT DROP AS
SELECT r.id,r.practice_id,r.item_id,r.developer_id,r.recorded_at,v.origin,v.ordered_at,v.id AS review_id,
 row_number() OVER(PARTITION BY r.practice_id,r.item_id,r.developer_id ORDER BY CASE WHEN v.origin IN ('EVENT','REQUEST') THEN 0 ELSE 1 END,v.ordered_at DESC,r.recorded_at DESC,v.id::text DESC,r.id::text DESC) AS rn
FROM result r JOIN review v ON v.id=r.review_id WHERE r.ended_at IS NULL;
UPDATE result loser SET ended_at=greatest(loser.recorded_at,winner.recorded_at),
 end_reason=CASE WHEN l.origin IN ('BACKFILL','SCHEDULE') AND w.origin IN ('EVENT','REQUEST') OR l.ordered_at>w.ordered_at THEN 'OUTRANKED' ELSE 'REPLACED' END
FROM _claim_rank l JOIN _claim_rank w ON w.practice_id=l.practice_id AND w.item_id=l.item_id AND w.developer_id IS NOT DISTINCT FROM l.developer_id AND w.rn=1
JOIN result winner ON winner.id=w.id WHERE loser.id=l.id AND l.rn>1;



CREATE TEMP TABLE _cutover_answered ON COMMIT DROP AS
 SELECT j.id AS review_id,j.workspace_id,p.id AS practice_id,(e->>'revisionId')::bigint AS version_id,
 (SELECT r.id FROM result r JOIN review current_review ON current_review.id=j.id
 JOIN _cutover_review owner ON owner.review_id=j.id
 WHERE r.review_id=(NULLIF(e->>'reviewId',''))::uuid AND r.practice_id=p.id AND r.practice_version_id=(e->>'revisionId')::bigint
 AND r.workspace_id=j.workspace_id AND r.item_id=current_review.item_id AND r.item_version IS NOT DISTINCT FROM current_review.item_version
 AND r.developer_id IS NOT DISTINCT FROM owner.developer_id) AS result_id
 FROM _cutover_old_agent_job j CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(j.evidence_snapshot->'answeredPractices')='array' THEN j.evidence_snapshot->'answeredPractices' ELSE '[]'::jsonb END) e
 JOIN practice p ON p.workspace_id=j.workspace_id AND p.slug=e->>'practiceSlug';
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_old_agent_job j CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(j.evidence_snapshot->'answeredPractices')='array' THEN j.evidence_snapshot->'answeredPractices' ELSE '[]'::jsonb END) e WHERE NOT EXISTS(SELECT 1 FROM practice p WHERE p.workspace_id=j.workspace_id AND p.slug=e->>'practiceSlug')) THEN RAISE EXCEPTION 'answered practice is not in workspace'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_answered GROUP BY review_id,practice_id HAVING count(*)>1) THEN RAISE EXCEPTION 'answered practice is ambiguous'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_answered a JOIN review_practice p ON p.review_id=a.review_id AND p.practice_id=a.practice_id WHERE a.version_id IS DISTINCT FROM p.practice_version_id AND EXISTS(SELECT 1 FROM result r WHERE r.review_id=a.review_id AND r.practice_id=a.practice_id)) THEN RAISE EXCEPTION 'answered version conflicts with admission'; END IF;
END $$;
INSERT INTO review_practice(review_id,practice_id,workspace_id,practice_version_id,status,reason,items_listed,listing_complete)
 SELECT review_id,practice_id,workspace_id,version_id,CASE WHEN result_id IS NULL THEN 'WITHHELD' ELSE 'DONE' END,CASE WHEN result_id IS NULL THEN 'LEGACY_REUSE_UNBOUND' END,1,true FROM _cutover_answered
 ON CONFLICT(review_id,practice_id) DO UPDATE SET practice_version_id=EXCLUDED.practice_version_id,status=EXCLUDED.status,reason=EXCLUDED.reason,items_listed=1,listing_complete=true
 WHERE NOT EXISTS(SELECT 1 FROM result r WHERE r.review_id=EXCLUDED.review_id AND r.practice_id=EXCLUDED.practice_id);
INSERT INTO review_item(workspace_id,review_id,practice_id,item_id,item_version,state,result_id,job_id,reason)
 SELECT a.workspace_id,a.review_id,a.practice_id,r.item_id,r.item_version,CASE WHEN a.result_id IS NULL THEN 'WITHHELD' ELSE 'REUSED' END,a.result_id,a.review_id,CASE WHEN a.result_id IS NULL THEN 'LEGACY_REUSE_UNBOUND' END
 FROM _cutover_answered a JOIN review r ON r.id=a.review_id WHERE NOT EXISTS(SELECT 1 FROM result produced WHERE produced.review_id=a.review_id AND produced.practice_id=a.practice_id)
 ON CONFLICT(review_id,practice_id,item_id) DO UPDATE SET state=EXCLUDED.state,result_id=EXCLUDED.result_id,reason=EXCLUDED.reason;


UPDATE review_job j SET input=jsonb_build_object('itemId',r.item_id,'assignments',COALESCE(
 (SELECT jsonb_agg(jsonb_build_object('reviewId',a.review_id,'practiceId',a.practice_id,'itemId',a.item_id) ORDER BY a.practice_id,a.item_id)
  FROM review_item a WHERE a.review_id=j.review_id AND a.workspace_id=j.workspace_id),'[]'::jsonb))
 FROM review r WHERE r.id=j.review_id AND r.workspace_id=j.workspace_id;

CREATE FUNCTION pg_temp.cutover_stop(v text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE v
 WHEN 'COMPOSER_DEDUPED' THEN 'NOTHING_NEW' WHEN 'REACTED_DISPUTED' THEN 'REACTED_DISAGREE'
 WHEN 'ARTIFACT_GONE' THEN 'ITEM_GONE' WHEN 'ARTIFACT_CLOSED' THEN 'ITEM_CLOSED' WHEN 'ARTIFACT_MERGED' THEN 'ITEM_MERGED'
 WHEN 'ARTIFACT_DRAFT' THEN 'ITEM_STATE_INELIGIBLE' WHEN 'RECIPIENT_OPTED_OUT' THEN 'RECIPIENT_UNAVAILABLE'
 WHEN 'OUTSIDE_CURRENT_COVERAGE' THEN 'OUTSIDE_CURRENT_SCOPE' WHEN 'OBSERVATION_INVALIDATED' THEN 'RESULT_MARKED_INCORRECT'
 WHEN 'REVIEWED_REVISION_CHANGED' THEN 'REVIEWED_VERSION_CHANGED' ELSE v END $$;
CREATE TEMP TABLE _cutover_send_parent(dispatch_id uuid PRIMARY KEY,feedback_id uuid NOT NULL,workspace_id bigint NOT NULL,review_id uuid NOT NULL,developer_id bigint NOT NULL) ON COMMIT DROP;
INSERT INTO _cutover_send_parent
 SELECT d.id,coalesce(d.feedback_id,f.id,d.id),d.workspace_id,r.review_id,coalesce(p.account_id,r.developer_id)
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_review r ON r.job_id=d.agent_job_id AND r.workspace_id=d.workspace_id
 LEFT JOIN LATERAL(SELECT x.id,x.recipient_user_id FROM _cutover_old_feedback x WHERE x.agent_job_id=d.agent_job_id AND x.workspace_id=d.workspace_id AND x.channel='IN_CONTEXT' AND x.position IN(0,5000) ORDER BY (x.position=0) DESC,x.created_at,x.id LIMIT 1) f ON d.feedback_id IS NULL
 LEFT JOIN _cutover_old_feedback approved ON approved.id=d.feedback_id
 LEFT JOIN _cutover_person p ON p.user_id=coalesce(approved.recipient_user_id,f.recipient_user_id);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_send_parent GROUP BY feedback_id HAVING count(*)>1) THEN RAISE EXCEPTION 'multiple physical sends resolve to one feedback'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback f LEFT JOIN _cutover_person p ON p.user_id=f.recipient_user_id LEFT JOIN _cutover_person subject ON subject.user_id=f.about_user_id WHERE p.account_id IS NULL OR p.account_id IS DISTINCT FROM subject.account_id) THEN RAISE EXCEPTION 'feedback person is ambiguous'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback_dispatch d WHERE NOT EXISTS(SELECT 1 FROM _cutover_send_parent p WHERE p.dispatch_id=d.id)) THEN RAISE EXCEPTION 'send cannot resolve its review/person'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback_dispatch d JOIN _cutover_old_feedback f ON f.id=d.feedback_id WHERE d.body IS DISTINCT FROM coalesce(f.body,'')) THEN RAISE EXCEPTION 'approved summary text differs from its released proposal'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback_dispatch d WHERE d.package_content->>'inlineMarker' IS NOT NULL AND d.package_content->>'inlineMarker' IS DISTINCT FROM CASE WHEN d.feedback_id IS NOT NULL THEN '<!-- hephaestus-approved-package:'||d.feedback_id||' -->' ELSE '<!-- hephaestus-review-package:'||d.agent_job_id||' -->' END) THEN RAISE EXCEPTION 'sealed marker differs from its released package'; END IF;
END $$;
INSERT INTO feedback(id,workspace_id,review_id,item_id,developer_id,destination,state,stop_reason,body,checks,replaces_id,created_at,delivered_at)
 SELECT f.id,f.workspace_id,f.agent_job_id,CASE WHEN f.channel='IN_CONTEXT' THEN r.item_id ELSE i.item_id END,p.account_id,
 CASE f.channel WHEN 'IN_CONTEXT' THEN 'ON_WORK' WHEN 'IN_APP' THEN 'PRACTICE_PAGE' WHEN 'IN_CHAT' THEN 'CONVERSATION' END,
 CASE f.delivery_state WHEN 'PREPARED' THEN 'READY' WHEN 'PARTIALLY_DELIVERED' THEN 'DELIVERED' WHEN 'PARTIALLY_FAILED' THEN 'DELIVERED' WHEN 'SUPPRESSED' THEN 'WITHHELD' WHEN 'DISCARDED' THEN 'REJECTED' WHEN 'SUPERSEDED' THEN 'REPLACED' ELSE f.delivery_state END,
 CASE WHEN f.delivery_state='UNCONFIRMED' THEN 'DELIVERY_UNCONFIRMED' ELSE pg_temp.cutover_stop(f.suppression_reason) END,
 f.body,jsonb_build_object('MIGRATION',jsonb_build_object('deliveryState',f.delivery_state,'stopReason',f.suppression_reason,'reviewedVersion',f.reviewed_revision)),f.replaces_id,f.created_at,
 COALESCE(f.delivered_at,(SELECT min(c.created_at) FROM _cutover_old_feedback_placement c WHERE c.feedback_id=f.id AND (c.posted_comment_ref IS NOT NULL OR c.chat_message_id IS NOT NULL) AND f.delivery_state<>'UNCONFIRMED'),
 (SELECT min(d.updated_at) FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id WHERE sp.feedback_id=f.id AND d.delivered_external_ref IS NOT NULL))
 FROM _cutover_old_feedback f JOIN _cutover_person p ON p.user_id=f.recipient_user_id JOIN review r ON r.id=f.agent_job_id AND r.workspace_id=f.workspace_id
 LEFT JOIN _cutover_item i ON(i.workspace_id,i.old_kind,i.old_source_id)=(f.workspace_id,f.artifact_kind,f.artifact_id);
INSERT INTO feedback(id,workspace_id,review_id,item_id,developer_id,destination,state,stop_reason,body,checks,created_at,delivered_at)
 SELECT sp.feedback_id,d.workspace_id,sp.review_id,r.item_id,sp.developer_id,'ON_WORK',
 CASE WHEN d.delivered_external_ref IS NOT NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(pg_temp.cutover_array(d.delivered_placements)) e WHERE nullif(e->>'externalRef','') IS NOT NULL AND e->>'disposition' IN('POSTED','FELL_BACK','PRESERVED_EXISTING')) THEN 'DELIVERED'
 WHEN d.state='SUPPRESSED' THEN 'WITHHELD' WHEN d.state='FAILED' THEN 'FAILED' WHEN d.state='SENT' THEN 'WITHHELD'
 WHEN d.write_started OR d.inline_write_started IS DISTINCT FROM false THEN 'UNCONFIRMED' ELSE 'READY' END,
 CASE WHEN d.state='SENT' AND d.delivered_external_ref IS NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(pg_temp.cutover_array(d.delivered_placements)) e WHERE nullif(e->>'externalRef','') IS NOT NULL) THEN 'NOTHING_NEW' ELSE pg_temp.cutover_stop(d.suppression_reason) END,
 d.body,jsonb_build_object('MIGRATION',jsonb_build_object('dispatchId',d.id,'state',d.state,'stopReason',d.suppression_reason,'renderedTextKnown',(d.feedback_id IS NOT NULL OR d.package_content->>'inlineMarker' IS NOT NULL))),d.created_at,
 CASE WHEN d.delivered_external_ref IS NOT NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(pg_temp.cutover_array(d.delivered_placements)) e WHERE nullif(e->>'externalRef','') IS NOT NULL AND e->>'disposition' IN('POSTED','FELL_BACK','PRESERVED_EXISTING')) THEN d.updated_at END
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id JOIN review r ON r.id=sp.review_id
 WHERE NOT EXISTS(SELECT 1 FROM feedback f WHERE f.id=sp.feedback_id);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback_observation b JOIN feedback f ON f.id=b.feedback_id LEFT JOIN _cutover_result r ON r.observation_id=b.observation_id AND r.workspace_id=f.workspace_id AND r.developer_id=f.developer_id WHERE r.result_id IS NULL) THEN RAISE EXCEPTION 'basis cannot resolve to the same workspace/developer'; END IF;
END $$;
INSERT INTO feedback_basis(id,workspace_id,feedback_id,result_id,problem_id,developer_id,ordinal)
 SELECT gen_random_uuid(),f.workspace_id,b.feedback_id,r.result_id,r.problem_id,f.developer_id,min(b.ordinal)
 FROM _cutover_old_feedback_observation b JOIN feedback f ON f.id=b.feedback_id JOIN _cutover_result r ON r.observation_id=b.observation_id AND r.workspace_id=f.workspace_id AND r.developer_id=f.developer_id
 GROUP BY f.workspace_id,b.feedback_id,r.result_id,r.problem_id,f.developer_id;
CREATE TEMP TABLE _cutover_contributors ON COMMIT DROP AS
 SELECT sp.feedback_id,sp.review_id,sp.workspace_id,sp.developer_id,e.value AS occurrence_key,e.ordinal
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id
 CROSS JOIN LATERAL jsonb_array_elements_text(pg_temp.cutover_array(d.package_content->'summaryContributors')) WITH ORDINALITY e(value,ordinal)
 UNION ALL SELECT sp.feedback_id,sp.review_id,sp.workspace_id,sp.developer_id,e.value,n.ordinal
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id
 CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(d.package_content->'diffNotes')) WITH ORDINALITY n(value,ordinal)
 CROSS JOIN LATERAL jsonb_array_elements_text(pg_temp.cutover_array(n.value->'contributors')) e(value);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_contributors c WHERE (SELECT count(*) FROM _cutover_old_observation o JOIN _cutover_result r ON r.observation_id=o.id WHERE(o.occurrence_key=c.occurrence_key OR o.id::text=c.occurrence_key) AND o.agent_job_id=c.review_id AND r.workspace_id=c.workspace_id AND r.developer_id=c.developer_id)<>1) THEN RAISE EXCEPTION 'sealed contributor cannot resolve exactly'; END IF;
END $$;
INSERT INTO feedback_basis(id,workspace_id,feedback_id,result_id,problem_id,developer_id,ordinal)
 SELECT gen_random_uuid(),c.workspace_id,c.feedback_id,r.result_id,r.problem_id,c.developer_id,min(c.ordinal)::integer
 FROM _cutover_contributors c JOIN _cutover_old_observation o ON(o.occurrence_key=c.occurrence_key OR o.id::text=c.occurrence_key) AND o.agent_job_id=c.review_id
 JOIN _cutover_result r ON r.observation_id=o.id AND r.workspace_id=c.workspace_id AND r.developer_id=c.developer_id
 WHERE NOT EXISTS(SELECT 1 FROM feedback_basis b WHERE b.feedback_id=c.feedback_id AND b.result_id=r.result_id AND b.problem_id IS NOT DISTINCT FROM r.problem_id)
 GROUP BY c.workspace_id,c.feedback_id,r.result_id,r.problem_id,c.developer_id;



CREATE TEMP TABLE _cutover_completion_parent ON COMMIT DROP AS
 SELECT c.job_id,gen_random_uuid() AS feedback_id,c.workspace_id,r.developer_id,c.review,c.accepted_at,c.review_digest
 FROM _cutover_old_public_review_completion c JOIN _cutover_review r ON r.job_id=c.job_id AND r.workspace_id=c.workspace_id
 WHERE c.review IS NOT NULL AND c.review<>'null'::jsonb
 AND NOT EXISTS(SELECT 1 FROM _cutover_send_parent sp WHERE sp.review_id=r.review_id)
 AND NOT EXISTS(SELECT 1 FROM _cutover_old_feedback f WHERE f.agent_job_id=c.job_id AND f.channel='IN_CONTEXT' AND f.position IN(0,5000));
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_completion_parent WHERE developer_id IS NULL) THEN RAISE EXCEPTION 'accepted composition has no exact developer'; END IF;
END $$;
INSERT INTO feedback(id,workspace_id,review_id,item_id,developer_id,destination,state,stop_reason,body,checks,created_at)
 SELECT c.feedback_id,c.workspace_id,c.job_id,r.item_id,c.developer_id,'ON_WORK','WITHHELD',CASE WHEN r.stop_reason='CONTRACT_CHANGED' THEN 'REVIEW_CANCELLED' ELSE 'APPROVAL_NO_LONGER_ELIGIBLE' END,c.review->'summary'->>'body',
 jsonb_build_object('MIGRATION',jsonb_build_object('acceptedReviewDigest',c.review_digest,'writeVisibility','UNKNOWN')),c.accepted_at
 FROM _cutover_completion_parent c JOIN review r ON r.id=c.job_id;
CREATE TEMP TABLE _cutover_completion_basis ON COMMIT DROP AS
 SELECT c.feedback_id,c.job_id,c.workspace_id,c.developer_id,x.value AS old_key
 FROM _cutover_completion_parent c CROSS JOIN LATERAL jsonb_array_elements_text(pg_temp.cutover_array(c.review->'summary'->'basedOn')) x
 UNION ALL SELECT c.feedback_id,c.job_id,c.workspace_id,c.developer_id,x.value
 FROM _cutover_completion_parent c CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(c.review->'inline')||pg_temp.cutover_array(c.review->'withheld')) note
 CROSS JOIN LATERAL jsonb_array_elements_text(pg_temp.cutover_array(note->'basedOn')) x;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_completion_basis c WHERE (SELECT count(*) FROM _cutover_old_observation o JOIN _cutover_result r ON r.observation_id=o.id AND r.workspace_id=c.workspace_id AND r.developer_id=c.developer_id WHERE o.agent_job_id=c.job_id AND(o.occurrence_key=c.old_key OR o.id::text=c.old_key))<>1) THEN RAISE EXCEPTION 'accepted contributor has no exact result'; END IF;
END $$;
INSERT INTO feedback_basis(id,workspace_id,feedback_id,result_id,problem_id,developer_id,ordinal)
 SELECT gen_random_uuid(),c.workspace_id,c.feedback_id,r.result_id,r.problem_id,c.developer_id,0
 FROM _cutover_completion_basis c JOIN _cutover_old_observation o ON o.agent_job_id=c.job_id AND(o.occurrence_key=c.old_key OR o.id::text=c.old_key)
 JOIN _cutover_result r ON r.observation_id=o.id AND r.workspace_id=c.workspace_id AND r.developer_id=c.developer_id
 GROUP BY c.workspace_id,c.feedback_id,r.result_id,r.problem_id,c.developer_id;

CREATE TEMP TABLE _cutover_copy_candidate(
 candidate_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,old_copy_id uuid,feedback_id uuid NOT NULL,source varchar(16) NOT NULL,source_order bigint NOT NULL,
 kind varchar(16) NOT NULL,body text,path text,start_line integer,end_line integer,side varchar(3),write_key text,write_marker text,state varchar(16) NOT NULL,
 write_started_at timestamptz,external_ref text,external_url text,chat_message_id uuid,created_at timestamptz NOT NULL,posted_at timestamptz,stop_reason varchar(48),last_error varchar(512)) ON COMMIT DROP;
INSERT INTO _cutover_copy_candidate(old_copy_id,feedback_id,source,source_order,kind,body,path,start_line,end_line,side,state,external_ref,external_url,chat_message_id,created_at,posted_at)
 SELECT p.id,p.feedback_id,'PLACEMENT',row_number() OVER(PARTITION BY p.feedback_id ORDER BY p.created_at,p.id::text),
 CASE p.placement_type WHEN 'SUMMARY' THEN 'SUMMARY' WHEN 'INLINE' THEN 'LINE_NOTE' WHEN 'LOCATION_COMMENT' THEN 'FILE_NOTE' WHEN 'CONVERSATION_TURN' THEN 'CHAT_TURN' END,
 CASE WHEN p.placement_type='CONVERSATION_TURN' THEN
 (SELECT CASE WHEN count(*)=1 THEN min(part->'data'->>'text') END
  FROM chat_message cm CROSS JOIN LATERAL jsonb_array_elements(cm.parts) WITH ORDINALITY x(part,n)
  WHERE cm.id=p.chat_message_id AND cm.workspace_id=f.workspace_id AND part->>'type'='data-observation'
   AND nullif(btrim(part->'data'->>'text'),'') IS NOT NULL
   AND EXISTS(SELECT 1 FROM _cutover_old_feedback_observation b
     WHERE b.feedback_id=f.id AND b.observation_id::text=part->'data'->>'observationId')) END,
 p.anchor_path,p.anchor_start_line,coalesce(p.anchor_end_line,p.anchor_start_line),p.anchor_side,
 CASE WHEN f.delivery_state='UNCONFIRMED' THEN 'WITHHELD' ELSE 'POSTED' END,p.posted_comment_ref,p.posted_comment_url,p.chat_message_id,p.created_at,
 CASE WHEN f.delivery_state<>'UNCONFIRMED' THEN p.created_at END
 FROM _cutover_old_feedback_placement p JOIN _cutover_old_feedback f ON f.id=p.feedback_id;
INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,body,path,start_line,end_line,write_key,state,created_at)
 SELECT f.id,'PROPOSED',n,CASE p->>'type' WHEN 'SUMMARY' THEN 'SUMMARY' WHEN 'INLINE' THEN 'LINE_NOTE' WHEN 'LOCATION_COMMENT' THEN 'FILE_NOTE' WHEN 'CONVERSATION_TURN' THEN 'CHAT_TURN' END,
 CASE WHEN p->>'type'<>'SUMMARY' THEN p->>'body' END,p->>'path',(p->>'startLine')::integer,coalesce((p->>'endLine')::integer,(p->>'startLine')::integer),coalesce(p->>'deliveryKey',p->>'recurrenceKey'),'PLANNED',f.created_at
 FROM _cutover_old_feedback f CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(f.proposed_placements)) WITH ORDINALITY x(p,n);
INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,body,path,start_line,end_line,write_key,write_marker,state,created_at)
 SELECT sp.feedback_id,'PACKAGE',n,'LINE_NOTE',note->>'body',note->>'filePath',(note->>'startLine')::integer,coalesce((note->>'endLine')::integer,(note->>'startLine')::integer),
 CASE WHEN d.feedback_id IS NOT NULL THEN 'approved:'||d.feedback_id||':'||(n-1)::text ELSE note->>'deliveryKey' END,
 COALESCE(d.package_content->>'inlineMarker',CASE WHEN d.feedback_id IS NOT NULL THEN '<!-- hephaestus-approved-package:'||d.feedback_id||' -->' ELSE '<!-- hephaestus-diff-note -->' END),'PLANNED',d.created_at
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id
 CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(d.package_content->'diffNotes')) WITH ORDINALITY x(note,n);
INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,write_key,write_marker,state,write_started_at,external_ref,external_url,created_at,posted_at)
 SELECT sp.feedback_id,'SUMMARY',0,'SUMMARY',CASE WHEN d.feedback_id IS NOT NULL THEN d.feedback_id::text ELSE d.agent_job_id::text END,
 CASE WHEN d.feedback_id IS NOT NULL THEN '<!-- hephaestus:approved-feedback:'||d.feedback_id||' -->' ELSE '<!-- hephaestus:practice-review:'||d.agent_job_id||' -->' END,
 CASE WHEN d.delivered_external_ref IS NOT NULL THEN 'POSTED' WHEN d.write_started THEN 'WRITE_STARTED' ELSE 'PLANNED' END,
 CASE WHEN d.write_started THEN coalesce(d.write_started_at,d.created_at) END,d.delivered_external_ref,d.delivered_external_url,d.created_at,CASE WHEN d.delivered_external_ref IS NOT NULL THEN d.updated_at END
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id
 WHERE (nullif(btrim(d.package_content->>'mrNote'),'') IS NOT NULL AND NOT EXISTS
  (SELECT 1 FROM feedback f WHERE f.id=sp.feedback_id AND f.state='WITHHELD'))
 OR d.delivered_external_ref IS NOT NULL OR d.write_started;
CREATE TEMP TABLE _cutover_copy_receipt ON COMMIT DROP AS
 SELECT sp.feedback_id,d.id AS dispatch_id,n AS receipt_order,coalesce(receipt->>'deliveryKey',receipt->>'recurrenceKey') AS write_key,
 receipt->>'path' AS path,(receipt->>'startLine')::integer AS start_line,coalesce((receipt->>'endLine')::integer,(receipt->>'startLine')::integer) AS end_line,
 receipt->>'disposition' AS disposition,nullif(receipt->>'externalRef','') AS external_ref,receipt->>'externalUrl' AS external_url,
 receipt->'writeMayHaveStarted' AS write_may_have_started,receipt->>'placement' AS actual_placement,d.write_started_at,d.created_at,d.updated_at
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id
 CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(d.delivered_placements)) WITH ORDINALITY x(receipt,n);
INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,path,start_line,end_line,write_key,state,write_started_at,external_ref,external_url,created_at,posted_at)
 SELECT feedback_id,'RECEIPT',receipt_order,CASE actual_placement WHEN 'LOCATION_COMMENT' THEN 'FILE_NOTE' ELSE 'LINE_NOTE' END,path,start_line,end_line,write_key,
 CASE WHEN external_ref IS NOT NULL AND disposition IN('POSTED','FELL_BACK','PRESERVED_EXISTING') THEN 'POSTED' WHEN write_may_have_started IS DISTINCT FROM 'false'::jsonb THEN 'WRITE_STARTED' ELSE 'FAILED' END,
 CASE WHEN write_may_have_started IS DISTINCT FROM 'false'::jsonb THEN coalesce(write_started_at,created_at) END,external_ref,external_url,created_at,
 CASE WHEN external_ref IS NOT NULL AND disposition IN('POSTED','FELL_BACK','PRESERVED_EXISTING') THEN updated_at END FROM _cutover_copy_receipt;

INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,state,created_at,stop_reason)
 SELECT feedback_id,'COMPLETION',0,'SUMMARY','WITHHELD',accepted_at,'APPROVAL_NO_LONGER_ELIGIBLE' FROM _cutover_completion_parent WHERE nullif(btrim(review->'summary'->>'body'),'') IS NOT NULL;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_completion_parent c CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(c.review->'inline')) note
 LEFT JOIN _cutover_old_observation o ON o.agent_job_id=c.job_id AND(o.occurrence_key=note->'anchor'->>'observationId' OR o.id::text=note->'anchor'->>'observationId')
 WHERE o.id IS NULL OR o.workspace_id<>c.workspace_id OR (note->'anchor'->>'citationIndex')::integer<0 OR (note->'anchor'->>'citationIndex')::integer>=jsonb_array_length(o.evidence->'citations')) THEN RAISE EXCEPTION 'accepted inline anchor cannot resolve exactly'; END IF;
END $$;
INSERT INTO _cutover_copy_candidate(feedback_id,source,source_order,kind,body,path,start_line,end_line,side,state,created_at,stop_reason)
 SELECT c.feedback_id,'COMPLETION',n,'LINE_NOTE',note->>'body',citation->>'path',(citation->>'startLine')::integer,COALESCE((citation->>'endLine')::integer,(citation->>'startLine')::integer),citation->>'side','WITHHELD',c.accepted_at,'APPROVAL_NO_LONGER_ELIGIBLE'
 FROM _cutover_completion_parent c CROSS JOIN LATERAL jsonb_array_elements(pg_temp.cutover_array(c.review->'inline')) WITH ORDINALITY x(note,n)
 JOIN _cutover_old_observation o ON o.agent_job_id=c.job_id AND(o.occurrence_key=note->'anchor'->>'observationId' OR o.id::text=note->'anchor'->>'observationId')
 CROSS JOIN LATERAL(SELECT o.evidence->'citations'->((note->'anchor'->>'citationIndex')::integer) AS citation) a;

CREATE TEMP TABLE _cutover_physical_copy(LIKE feedback_copy INCLUDING DEFAULTS) ON COMMIT DROP;
ALTER TABLE _cutover_physical_copy ADD COLUMN plan_order bigint;
DO $$ DECLARE r record; existing _cutover_physical_copy%ROWTYPE; n bigint; chosen uuid; BEGIN
 FOR r IN SELECT * FROM _cutover_copy_candidate ORDER BY CASE source WHEN 'PLACEMENT' THEN 0 WHEN 'SUMMARY' THEN 1 WHEN 'PACKAGE' THEN 2 WHEN 'PROPOSED' THEN 3 ELSE 4 END,source_order,candidate_id LOOP
  SELECT count(*),(array_agg(c.id ORDER BY c.id::text))[1] INTO n,chosen FROM _cutover_physical_copy c WHERE c.feedback_id=r.feedback_id AND
   ((r.external_ref IS NOT NULL AND c.external_ref=r.external_ref) OR (r.write_key IS NOT NULL AND c.write_key=r.write_key) OR
    (r.kind='SUMMARY' AND c.kind='SUMMARY') OR (r.kind='CHAT_TURN' AND c.kind='CHAT_TURN' AND c.chat_message_id=r.chat_message_id) OR
    (r.kind IN('LINE_NOTE','FILE_NOTE') AND c.kind IN('LINE_NOTE','FILE_NOTE') AND c.path=r.path AND c.start_line IS NOT DISTINCT FROM r.start_line AND c.end_line IS NOT DISTINCT FROM r.end_line));
  IF n>1 THEN RAISE EXCEPTION 'ambiguous physical copy reconciliation for %',r.feedback_id; END IF;
  IF n=0 THEN
   INSERT INTO _cutover_physical_copy(id,workspace_id,feedback_id,kind,position,body,path,start_line,end_line,side,state,write_started_at,write_key,write_marker,external_ref,external_url,chat_message_id,created_at,posted_at,plan_order,stop_reason,last_error)
    SELECT coalesce(r.old_copy_id,gen_random_uuid()),f.workspace_id,r.feedback_id,r.kind,0,r.body,r.path,r.start_line,r.end_line,r.side,r.state,r.write_started_at,r.write_key,r.write_marker,r.external_ref,r.external_url,r.chat_message_id,r.created_at,r.posted_at,r.source_order,r.stop_reason,r.last_error FROM feedback f WHERE f.id=r.feedback_id;
  ELSE
   SELECT * INTO existing FROM _cutover_physical_copy WHERE id=chosen;
   IF r.old_copy_id IS NOT NULL AND r.old_copy_id<>chosen THEN RAISE EXCEPTION 'two released copy ids describe one physical copy'; END IF;
   IF r.external_ref IS NOT NULL AND existing.external_ref IS NOT NULL AND r.external_ref<>existing.external_ref THEN RAISE EXCEPTION 'conflicting provider receipt'; END IF;
   IF r.body IS NOT NULL AND existing.body IS NOT NULL AND r.body<>existing.body THEN RAISE EXCEPTION 'approved/sealed copy text mismatch'; END IF;
   IF r.write_key IS NOT NULL AND existing.write_key IS NOT NULL AND r.write_key<>existing.write_key THEN RAISE EXCEPTION 'copy write identity mismatch'; END IF;
   UPDATE _cutover_physical_copy SET body=coalesce(existing.body,r.body),side=coalesce(existing.side,r.side),write_key=coalesce(existing.write_key,r.write_key),write_marker=coalesce(existing.write_marker,r.write_marker),
    state=CASE WHEN existing.state='POSTED' OR r.state='POSTED' THEN 'POSTED' WHEN existing.state='WRITE_STARTED' OR r.state='WRITE_STARTED' THEN 'WRITE_STARTED' WHEN existing.state='WITHHELD' THEN 'WITHHELD' WHEN r.state='FAILED' THEN 'FAILED' ELSE existing.state END,
    kind=CASE WHEN existing.kind='FILE_NOTE' OR r.kind='FILE_NOTE' THEN 'FILE_NOTE' ELSE existing.kind END,
    write_started_at=coalesce(existing.write_started_at,r.write_started_at),external_ref=coalesce(existing.external_ref,r.external_ref),external_url=coalesce(existing.external_url,r.external_url),posted_at=coalesce(existing.posted_at,r.posted_at),
    plan_order=CASE WHEN r.source IN('PACKAGE','PROPOSED') THEN r.source_order ELSE existing.plan_order END,stop_reason=coalesce(existing.stop_reason,r.stop_reason),last_error=coalesce(existing.last_error,r.last_error) WHERE id=chosen;
  END IF;
 END LOOP;
END $$;
-- A missing old inline flag retains a possible-write fence, even if a later policy withheld its parent.
UPDATE _cutover_physical_copy c SET state='WRITE_STARTED',write_started_at=coalesce(c.write_started_at,d.write_started_at,d.created_at)
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id WHERE c.feedback_id=sp.feedback_id AND c.kind IN('LINE_NOTE','FILE_NOTE') AND c.state NOT IN('POSTED','WRITE_STARTED') AND d.inline_write_started IS DISTINCT FROM false;
UPDATE _cutover_physical_copy c SET state='WITHHELD',stop_reason=f.stop_reason FROM feedback f WHERE f.id=c.feedback_id AND c.state='PLANNED' AND f.state IN('WITHHELD','REJECTED','REPLACED','UNCONFIRMED');
UPDATE _cutover_physical_copy c SET state='FAILED',last_error=d.last_error FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id WHERE c.feedback_id=sp.feedback_id AND c.state='PLANNED' AND d.state='FAILED';
WITH ranked AS(SELECT id,row_number() OVER(PARTITION BY feedback_id ORDER BY (kind='SUMMARY') DESC,plan_order,created_at,id::text)-1 AS n FROM _cutover_physical_copy)
UPDATE _cutover_physical_copy c SET position=r.n::integer FROM ranked r WHERE r.id=c.id;
INSERT INTO feedback_copy(id,workspace_id,feedback_id,kind,position,body,path,start_line,end_line,side,stop_reason,last_error,state,write_started_at,write_key,write_marker,external_ref,external_url,chat_message_id,created_at,posted_at)
 SELECT id,workspace_id,feedback_id,kind,position,body,path,start_line,end_line,side,stop_reason,last_error,state,write_started_at,write_key,write_marker,external_ref,external_url,chat_message_id,created_at,posted_at FROM _cutover_physical_copy;
UPDATE feedback f SET state='UNCONFIRMED',stop_reason='DELIVERY_UNCONFIRMED' WHERE EXISTS(SELECT 1 FROM feedback_copy c WHERE c.feedback_id=f.id AND c.state='WRITE_STARTED');
INSERT INTO feedback_send(feedback_id,workspace_id,action,state,attempts,next_attempt_at,last_error,created_at,updated_at)
 SELECT sp.feedback_id,d.workspace_id,'POST',CASE WHEN f.state='UNCONFIRMED' THEN CASE WHEN f.destination='ON_WORK' AND EXISTS(SELECT 1 FROM feedback_copy c WHERE c.feedback_id=f.id AND c.state='WRITE_STARTED') THEN 'UNCERTAIN' ELSE 'DONE' END
 WHEN d.state IN('SENT','SUPPRESSED','FAILED') OR f.state IN('DELIVERED','WITHHELD','REJECTED','REPLACED','FAILED') THEN 'DONE'
 WHEN d.state IN('CLAIMED','UNCERTAIN') THEN 'UNCERTAIN' ELSE 'PENDING' END,d.attempt_count,d.next_attempt_at,d.last_error,d.created_at,d.updated_at
 FROM _cutover_old_feedback_dispatch d JOIN _cutover_send_parent sp ON sp.dispatch_id=d.id JOIN feedback f ON f.id=sp.feedback_id;
UPDATE feedback f SET state='WITHHELD',stop_reason='APPROVAL_NO_LONGER_ELIGIBLE'
 WHERE f.state IN('READY','AWAITING_APPROVAL') AND NOT EXISTS(SELECT 1 FROM feedback_basis b WHERE b.feedback_id=f.id) AND NOT EXISTS(SELECT 1 FROM feedback_copy c WHERE c.feedback_id=f.id AND c.state IN('WRITE_STARTED','POSTED'));
UPDATE feedback_send s SET state='DONE' FROM feedback f WHERE f.id=s.feedback_id AND f.state='WITHHELD';



-- Correction custody moves with the existing copy. RETRACT never creates a provider comment.
UPDATE feedback_copy c SET state='RETRACTED',stop_reason='RESULT_MARKED_INCORRECT'
 FROM feedback_basis b JOIN _cutover_old_observation_invalidation m ON m.observation_id=b.result_id
 WHERE c.feedback_id=b.feedback_id AND c.kind='SUMMARY' AND c.state='POSTED' AND m.restored_at IS NULL AND m.provider_copy IN('UPDATED','INLINE_REMAINS');
CREATE TEMP TABLE _cutover_correction ON COMMIT DROP AS
 SELECT f.id AS feedback_id,f.workspace_id,min(m.provider_copy_retry_at) AS retry_at,bool_or(m.provider_copy='UNRESOLVED') AS uncertain
 FROM feedback f JOIN feedback_basis b ON b.feedback_id=f.id JOIN _cutover_old_observation_invalidation m ON m.observation_id=b.result_id
 WHERE f.destination='ON_WORK' AND(m.provider_copy IN('PENDING','UNRESOLVED') OR(m.restored_at IS NULL AND m.provider_copy='INLINE_REMAINS' AND EXISTS(SELECT 1 FROM feedback_copy c WHERE c.feedback_id=f.id AND c.kind IN('LINE_NOTE','FILE_NOTE') AND c.state='POSTED')))
 AND EXISTS(SELECT 1 FROM feedback_copy c WHERE c.feedback_id=f.id AND(c.external_ref IS NOT NULL OR c.state='WRITE_STARTED'))
 GROUP BY f.id,f.workspace_id;
INSERT INTO feedback_send(feedback_id,workspace_id,action,state,attempts,next_attempt_at)
 SELECT feedback_id,workspace_id,'RETRACT',CASE WHEN uncertain THEN 'UNCERTAIN' ELSE 'PENDING' END,0,retry_at FROM _cutover_correction
 ON CONFLICT(feedback_id) DO UPDATE SET action='RETRACT',state=EXCLUDED.state,lease_owner=NULL,lease_expires_at=NULL,next_attempt_at=EXCLUDED.next_attempt_at;
UPDATE feedback f SET state='WITHHELD',stop_reason='RESULT_MARKED_INCORRECT'
 WHERE f.state IN('READY','AWAITING_APPROVAL') AND EXISTS(SELECT 1 FROM feedback_basis b JOIN result_mark m ON m.result_id=b.result_id WHERE b.feedback_id=f.id AND m.kind='INCORRECT' AND m.removed_at IS NULL);
UPDATE feedback_send s SET state='DONE' FROM feedback f WHERE f.id=s.feedback_id AND f.state='WITHHELD' AND s.action='POST';
WITH marks AS(SELECT b.feedback_id,jsonb_agg(jsonb_build_object('markId',m.id,'providerCopy',m.provider_copy,'retryAt',m.provider_copy_retry_at) ORDER BY m.id::text) AS prior
 FROM feedback_basis b JOIN _cutover_old_observation_invalidation m ON m.observation_id=b.result_id GROUP BY b.feedback_id)
UPDATE feedback f SET checks=f.checks||jsonb_build_object('MIGRATION_CORRECTION',m.prior) FROM marks m WHERE m.feedback_id=f.id;

CREATE FUNCTION feedback_content_digest(p_id uuid) RETURNS varchar(64) LANGUAGE sql STABLE STRICT AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object('workspaceId',f.workspace_id,'reviewId',f.review_id,'developerId',f.developer_id,'destination',f.destination,'itemId',f.item_id,'itemVersion',r.item_version,'body',f.body,
 'basis',COALESCE((SELECT jsonb_agg(jsonb_build_object('resultId',b.result_id,'problemId',b.problem_id) ORDER BY b.result_id::text,b.problem_id::text NULLS FIRST) FROM feedback_basis b WHERE b.feedback_id=f.id),'[]'::jsonb),
 'copies',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',v.id,'kind',CASE WHEN v.kind IN('LINE_NOTE','FILE_NOTE') THEN 'NOTE' ELSE v.kind END,'position',v.position,'body',CASE WHEN v.kind='CHAT_TURN' THEN NULL ELSE v.body END,'path',v.path,'startLine',v.start_line,'endLine',v.end_line,'side',v.side) ORDER BY v.position) FROM feedback_copy v WHERE v.feedback_id=f.id),'[]'::jsonb))::text,'UTF8')),'hex')::varchar(64)
 FROM feedback f JOIN review r ON r.id=f.review_id AND r.workspace_id=f.workspace_id WHERE f.id=p_id
$$;
CREATE FUNCTION feedback_package_digest(p_digests text[]) RETURNS varchar(64) LANGUAGE plpgsql IMMUTABLE STRICT AS $$
BEGIN
 IF array_ndims(p_digests)>1 OR EXISTS(SELECT 1 FROM unnest(p_digests) d WHERE d IS NULL OR d !~ '^[0-9a-f]{64}$') THEN
  RAISE EXCEPTION 'package pieces must be an ordered list of SHA-256 digests' USING ERRCODE='23514';
 END IF;
 RETURN encode(sha256(convert_to(to_jsonb(p_digests)::text,'UTF8')),'hex')::varchar(64);
END $$;
UPDATE feedback f SET checks=jsonb_set(f.checks,'{MIGRATION,approvalDigest}',to_jsonb(a.content_digest)) FROM _cutover_old_feedback_approval a WHERE a.feedback_id=f.id;
INSERT INTO feedback_decision(id,workspace_id,feedback_id,action,actor_account_id,reason,note,content_digest,decided_at)
 SELECT a.id,a.workspace_id,a.feedback_id,CASE a.decision WHEN 'APPROVED' THEN 'APPROVE' WHEN 'REJECTED' THEN 'REJECT' END,account.id,a.rejection_reason,a.rejection_note,feedback_content_digest(a.feedback_id),a.decided_at
 FROM _cutover_old_feedback_approval a LEFT JOIN account ON account.id=a.actor_account_id;
INSERT INTO feedback_decision(id,workspace_id,feedback_id,action,actor_account_id,note,decided_at)
 SELECT id,workspace_id,feedback_id,'WITHDRAW',withdrawn_by_account_id,reason,withdrawn_at FROM _cutover_old_feedback_withdrawal;
INSERT INTO feedback_decision(id,workspace_id,feedback_id,action,actor_account_id,note,decided_at)
 SELECT gen_random_uuid(),workspace_id,feedback_id,'RESTORE',restored_by_account_id,restoration_reason,restored_at FROM _cutover_old_feedback_withdrawal WHERE restored_at IS NOT NULL;
INSERT INTO feedback_response(id,workspace_id,feedback_id,resolution,usefulness,comment,created_at)
 SELECT r.id,f.workspace_id,r.feedback_id,CASE r.action WHEN 'DISPUTED' THEN 'DISAGREE' ELSE r.action END,r.usefulness,r.explanation,r.created_at FROM _cutover_old_reaction r JOIN feedback f ON f.id=r.feedback_id;
WITH evaluations AS(SELECT feedback_id,jsonb_agg(pg_temp.cutover_citations(to_jsonb(e)) ORDER BY e.evaluated_at,e.id::text) AS payload FROM _cutover_old_delivery_policy_evaluation e WHERE feedback_id IS NOT NULL GROUP BY feedback_id)
UPDATE feedback f SET checks=f.checks||jsonb_build_object('MIGRATION_POLICY',e.payload) FROM evaluations e WHERE e.feedback_id=f.id;
WITH evaluations AS(SELECT agent_job_id,jsonb_agg(pg_temp.cutover_citations(to_jsonb(e)) ORDER BY e.evaluated_at,e.id::text) AS payload FROM _cutover_old_delivery_policy_evaluation e WHERE feedback_id IS NULL GROUP BY agent_job_id)
UPDATE review r SET checks=r.checks||jsonb_build_object('MIGRATION_POLICY',e.payload) FROM evaluations e WHERE e.agent_job_id=r.id;
-- Released data-observation links named verdicts; their UUID remains the Result UUID.
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM chat_message cm CROSS JOIN LATERAL jsonb_array_elements(cm.parts) p
  WHERE p->>'type'='data-observation' AND (
   jsonb_typeof(p->'data') IS DISTINCT FROM 'object'
   OR NOT coalesce(p->'data'->>'observationId' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$',false)
   OR (p->'data' ? 'text' AND jsonb_typeof(p->'data'->'text') NOT IN ('string','null'))
   OR (p->'data' ? 'resultId' AND p->'data'->>'resultId' IS DISTINCT FROM p->'data'->>'observationId'))) THEN
  RAISE EXCEPTION 'stored conversation verdict link is unrepresentable'; END IF;
 IF EXISTS(SELECT 1 FROM chat_message cm CROSS JOIN LATERAL jsonb_array_elements(cm.parts) p
  JOIN _cutover_result r ON r.observation_id::text=p->'data'->>'observationId'
  WHERE p->>'type'='data-observation' AND r.workspace_id<>cm.workspace_id) THEN
  RAISE EXCEPTION 'stored conversation verdict link crosses workspace'; END IF;
END $$;
WITH messages AS(SELECT cm.id,cm.workspace_id,jsonb_agg(
 CASE WHEN p->>'type'='data-observation' THEN jsonb_set(jsonb_set(p,'{type}','"data-result"'::jsonb),'{data}',
  ((p->'data')-'observationId')||jsonb_build_object('resultId',p->'data'->'observationId',
   'text',CASE WHEN jsonb_typeof(p->'data'->'text')='string' THEN p->'data'->'text' ELSE '""'::jsonb END))
 ELSE p END ORDER BY n) AS parts
 FROM chat_message cm CROSS JOIN LATERAL jsonb_array_elements(cm.parts) WITH ORDINALITY x(p,n)
 WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(cm.parts) q WHERE q->>'type'='data-observation')
 GROUP BY cm.id,cm.workspace_id)
UPDATE chat_message cm SET parts=m.parts FROM messages m WHERE cm.id=m.id AND cm.workspace_id=m.workspace_id;

-- Historical audit is inert Review data. Feedback checks contain only final typed stages.
WITH audits AS(SELECT review_id,jsonb_object_agg(id::text,checks ORDER BY id::text) AS payload
 FROM feedback WHERE checks<>'{}'::jsonb GROUP BY review_id)
UPDATE review r SET checks=jsonb_set(r.checks,'{MIGRATION}',coalesce(r.checks->'MIGRATION','{}'::jsonb)||jsonb_build_object('feedback',a.payload))
 FROM audits a WHERE a.review_id=r.id;
UPDATE feedback SET checks='{}'::jsonb WHERE checks<>'{}'::jsonb;
UPDATE review r SET checks=jsonb_set(r.checks-'MIGRATION_POLICY','{MIGRATION}',
 coalesce(r.checks->'MIGRATION','{}'::jsonb)||jsonb_build_object('policy',r.checks->'MIGRATION_POLICY'))
 WHERE jsonb_exists(r.checks, 'MIGRATION_POLICY');
UPDATE review_composition_basis SET payload=pg_temp.cutover_citations(payload);
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT conname FROM pg_constraint WHERE conrelid='workspace'::regclass AND contype='c'
  AND pg_get_constraintdef(oid) ~ 'practice_default_autonomy|practice_repository_coverage_mode|practice_person_coverage_mode|practice_skip_drafts'
 LOOP EXECUTE format('ALTER TABLE workspace DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT c.conname FROM pg_constraint c WHERE c.conrelid='chat_thread'::regclass AND c.contype='f'
  AND EXISTS(SELECT FROM pg_attribute a WHERE a.attrelid=c.conrelid AND a.attnum=ANY(c.conkey) AND a.attname IN ('user_id'))
 LOOP EXECUTE format('ALTER TABLE chat_thread DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT c.conname FROM pg_constraint c WHERE c.conrelid='chat_message'::regclass AND c.contype='f'
  AND EXISTS(SELECT FROM pg_attribute a WHERE a.attrelid=c.conrelid AND a.attnum=ANY(c.conkey) AND a.attname IN ('thread_id','parent_message_id'))
 LOOP EXECUTE format('ALTER TABLE chat_message DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT c.conname FROM pg_constraint c WHERE c.conrelid='auth_event'::regclass AND c.contype='f'
  AND EXISTS(SELECT FROM pg_attribute a WHERE a.attrelid=c.conrelid AND a.attnum=ANY(c.conkey) AND a.attname IN ('identity_link_id'))
 LOOP EXECUTE format('ALTER TABLE auth_event DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;

DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT c.conname FROM pg_constraint c WHERE c.conrelid='slack_message'::regclass AND c.contype='f'
  AND EXISTS(SELECT FROM pg_attribute a WHERE a.attrelid=c.conrelid AND a.attnum=ANY(c.conkey) AND a.attname IN ('author_member_id'))
 LOOP EXECUTE format('ALTER TABLE slack_message DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT c.conname FROM pg_constraint c WHERE c.conrelid='slack_channel_consent_event'::regclass AND c.contype='f'
  AND EXISTS(SELECT FROM pg_attribute a WHERE a.attrelid=c.conrelid AND a.attnum=ANY(c.conkey) AND a.attname IN ('actor_user_id'))
 LOOP EXECUTE format('ALTER TABLE slack_channel_consent_event DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;


