 IF old_name IS NULL THEN ALTER TABLE chat_message ADD CONSTRAINT uk_chat_message_tenant UNIQUE(id,workspace_id);
 ELSIF old_name<>'uk_chat_message_tenant' THEN EXECUTE format('ALTER TABLE chat_message RENAME CONSTRAINT %I TO uk_chat_message_tenant',old_name); END IF;
END $$;











