CREATE FUNCTION guard_practice_identity() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF ROW(NEW.id,NEW.workspace_id,NEW.slug,NEW.kind) IS DISTINCT FROM ROW(OLD.id,OLD.workspace_id,OLD.slug,OLD.kind) THEN RAISE EXCEPTION 'practice identity is immutable' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER practice_identity_immutable BEFORE UPDATE ON practice FOR EACH ROW EXECUTE FUNCTION guard_practice_identity();
CREATE FUNCTION guard_practice_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF (to_jsonb(NEW)-'created_by_account_id') IS DISTINCT FROM (to_jsonb(OLD)-'created_by_account_id') OR (NEW.created_by_account_id IS NOT NULL AND NEW.created_by_account_id IS DISTINCT FROM OLD.created_by_account_id) THEN RAISE EXCEPTION 'practice versions are immutable' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER practice_version_immutable BEFORE UPDATE ON practice_version FOR EACH ROW EXECUTE FUNCTION guard_practice_version();
CREATE FUNCTION enforce_practice_current_definition() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM practice p JOIN practice_version v ON(v.id,v.practice_id,v.workspace_id)=(p.current_version_id,p.id,p.workspace_id) WHERE p.id=NEW.id AND coalesce(practice_definition_complete(v.definition),false)) THEN RAISE EXCEPTION 'current practice definition is incomplete' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER practice_current_definition_complete AFTER INSERT OR UPDATE ON practice DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION enforce_practice_current_definition();
CREATE FUNCTION guard_feedback_copy_fence() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE shown_text text;
BEGIN
 IF OLD.write_started_at IS NOT NULL THEN
  IF NEW.write_started_at IS DISTINCT FROM OLD.write_started_at OR
     ROW(NEW.id,NEW.workspace_id,NEW.feedback_id,NEW.position,NEW.write_key,NEW.write_marker,NEW.path,NEW.start_line,NEW.end_line,NEW.side)
     IS DISTINCT FROM ROW(OLD.id,OLD.workspace_id,OLD.feedback_id,OLD.position,OLD.write_key,OLD.write_marker,OLD.path,OLD.start_line,OLD.end_line,OLD.side) THEN
   RAISE EXCEPTION 'physical write fence is immutable' USING ERRCODE='55000';
  END IF;
  IF NEW.chat_message_id IS DISTINCT FROM OLD.chat_message_id AND NOT
     (NEW.chat_message_id IS NULL AND NOT EXISTS(SELECT 1 FROM chat_message WHERE id=OLD.chat_message_id AND workspace_id=OLD.workspace_id)) THEN
   RAISE EXCEPTION 'conversation message binding is immutable' USING ERRCODE='55000';
  END IF;
  IF NEW.body IS DISTINCT FROM OLD.body THEN
   IF NOT(OLD.kind='CHAT_TURN' AND OLD.body IS NULL AND NEW.body IS NOT NULL AND
          OLD.posted_at IS NULL AND NEW.posted_at IS NOT NULL AND NEW.posted_at>=OLD.write_started_at AND
          OLD.state IN('WRITE_STARTED','FAILED') AND NEW.state='POSTED' AND
          NEW.chat_message_id IS NOT NULL AND NEW.chat_message_id IS NOT DISTINCT FROM OLD.chat_message_id) THEN
    RAISE EXCEPTION 'physical copy words are immutable' USING ERRCODE='55000';
   END IF;
   SELECT string_agg(part.value->>'text','' ORDER BY part.position) INTO shown_text
   FROM chat_message m JOIN chat_thread t ON(t.id,t.workspace_id)=(m.thread_id,m.workspace_id)
   JOIN feedback f ON(f.id,f.workspace_id)=(NEW.feedback_id,NEW.workspace_id) AND f.developer_id=t.account_id
   JOIN LATERAL jsonb_array_elements(m.parts) WITH ORDINALITY AS part(value,position) ON true
   WHERE m.id=NEW.chat_message_id AND m.workspace_id=NEW.workspace_id AND m.role='ASSISTANT' AND
         m.status='completed' AND part.value->>'type'='text';
   IF shown_text IS NULL OR shown_text ~ '^[[:space:]]*$' OR NEW.body IS DISTINCT FROM shown_text THEN
    RAISE EXCEPTION 'conversation receipt must contain the completed assistant words' USING ERRCODE='23514';
   END IF;
  END IF;
  IF OLD.kind='CHAT_TURN' AND OLD.posted_at IS NULL AND NEW.posted_at IS NOT NULL AND NEW.body IS NULL THEN
   RAISE EXCEPTION 'conversation receipt requires actual words' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.write_started_at IS NOT NULL AND NEW.kind='CHAT_TURN' THEN
  IF NEW.body IS NOT NULL OR NEW.state<>'WRITE_STARTED' OR NOT EXISTS(
     SELECT 1 FROM chat_message m JOIN chat_thread t ON(t.id,t.workspace_id)=(m.thread_id,m.workspace_id)
     JOIN feedback f ON(f.id,f.workspace_id)=(NEW.feedback_id,NEW.workspace_id) AND f.developer_id=t.account_id
     WHERE m.id=NEW.chat_message_id AND m.workspace_id=NEW.workspace_id AND m.role='ASSISTANT' AND f.destination='CONVERSATION') THEN
   RAISE EXCEPTION 'conversation fence requires its developer assistant message' USING ERRCODE='23514';
  END IF;
 END IF;
 IF OLD.kind<>NEW.kind AND NOT(OLD.kind='LINE_NOTE' AND NEW.kind='FILE_NOTE') THEN RAISE EXCEPTION 'copy form cannot change except acknowledged fallback' USING ERRCODE='55000'; END IF;
 IF OLD.external_ref IS NOT NULL AND NEW.external_ref IS DISTINCT FROM OLD.external_ref OR OLD.external_url IS NOT NULL AND NEW.external_url IS DISTINCT FROM OLD.external_url OR OLD.posted_at IS NOT NULL AND NEW.posted_at IS DISTINCT FROM OLD.posted_at THEN RAISE EXCEPTION 'physical write receipt is immutable' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER feedback_copy_fence_monotonic BEFORE UPDATE ON feedback_copy FOR EACH ROW EXECUTE FUNCTION guard_feedback_copy_fence();
CREATE FUNCTION guard_feedback_send_destination() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM feedback f WHERE f.id=NEW.feedback_id AND f.workspace_id=NEW.workspace_id AND f.destination='ON_WORK') THEN RAISE EXCEPTION 'only on-work feedback has a provider send' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER feedback_send_on_work BEFORE INSERT OR UPDATE ON feedback_send FOR EACH ROW EXECUTE FUNCTION guard_feedback_send_destination();
CREATE FUNCTION guard_feedback_history() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_TABLE_NAME='feedback_decision' THEN
  IF to_jsonb(NEW)-'actor_account_id' IS NOT DISTINCT FROM to_jsonb(OLD)-'actor_account_id' AND (NEW.actor_account_id IS NULL OR NEW.actor_account_id IS NOT DISTINCT FROM OLD.actor_account_id) THEN RETURN NEW; END IF;
 END IF;
 RAISE EXCEPTION 'feedback history is append-only' USING ERRCODE='55000';
END $$;
CREATE TRIGGER feedback_decision_append_only BEFORE UPDATE ON feedback_decision FOR EACH ROW EXECUTE FUNCTION guard_feedback_history();
CREATE TRIGGER feedback_response_append_only BEFORE UPDATE ON feedback_response FOR EACH ROW EXECUTE FUNCTION guard_feedback_history();


DO $$ DECLARE checked_row record; BEGIN
 IF EXISTS(SELECT 1 FROM _cutover_old_observation o LEFT JOIN result r ON r.id=o.id WHERE r.id IS NULL OR r.recorded_at<>o.observed_at) THEN RAISE EXCEPTION 'released result identity/time was lost'; END IF;
 IF EXISTS(SELECT 1 FROM result r LEFT JOIN item i ON i.id=r.item_id AND i.workspace_id=r.workspace_id WHERE i.id IS NULL) THEN RAISE EXCEPTION 'result has no tenant item'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_identity_link i LEFT JOIN identity n ON n.id=i.id WHERE n.id IS NULL OR n.account_id<>i.account_id OR n.provider_id<>i.provider_id OR n.provider_user_key<>i.subject OR n.team_key<>COALESCE(i.team_id,'') OR n.disabled_at IS DISTINCT FROM i.disabled_at) THEN RAISE EXCEPTION 'released identity or authority changed'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_practice_revision v LEFT JOIN practice_version n ON n.id=v.id WHERE n.id IS NULL OR n.practice_id<>v.practice_id OR n.number<>v.revision_number OR n.created_at<>v.created_at OR n.definition IS DISTINCT FROM pg_temp.cutover_columns(to_jsonb(v))) THEN RAISE EXCEPTION 'historical practice version changed'; END IF;
 IF EXISTS(SELECT 1 FROM practice p JOIN practice_version v ON v.id=p.current_version_id WHERE NOT coalesce(practice_definition_complete(v.definition),false)) THEN RAISE EXCEPTION 'current definition is incomplete'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback o LEFT JOIN feedback f ON f.id=o.id WHERE f.id IS NULL OR f.body IS DISTINCT FROM o.body OR f.created_at<>o.created_at OR(o.delivered_at IS NOT NULL AND f.delivered_at IS DISTINCT FROM o.delivered_at)) THEN RAISE EXCEPTION 'released feedback words or receipt changed'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback_placement o LEFT JOIN feedback_copy c ON c.id=o.id WHERE c.id IS NULL OR c.feedback_id<>o.feedback_id OR c.external_ref IS DISTINCT FROM o.posted_comment_ref OR c.external_url IS DISTINCT FROM o.posted_comment_url OR c.chat_message_id IS DISTINCT FROM o.chat_message_id) THEN RAISE EXCEPTION 'released physical copy was lost'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback_approval o LEFT JOIN feedback_decision d ON d.id=o.id WHERE d.id IS NULL OR d.feedback_id<>o.feedback_id OR d.decided_at<>o.decided_at OR d.note IS DISTINCT FROM o.rejection_note) THEN RAISE EXCEPTION 'approval history changed'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_reaction o LEFT JOIN feedback_response r ON r.id=o.id WHERE r.id IS NULL OR r.feedback_id<>o.feedback_id OR r.created_at<>o.created_at OR r.comment IS DISTINCT FROM o.explanation) THEN RAISE EXCEPTION 'response history changed'; END IF;
 IF EXISTS(SELECT 1 FROM feedback_send s JOIN _cutover_send_parent sp ON sp.feedback_id=s.feedback_id JOIN _cutover_old_feedback_dispatch d ON d.id=sp.dispatch_id WHERE d.state IN('SENT','SUPPRESSED','FAILED') AND s.action='POST' AND s.state='PENDING') THEN RAISE EXCEPTION 'terminal delivery was re-enqueued'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_feedback f WHERE f.delivery_state IN('PARTIALLY_DELIVERED','PARTIALLY_FAILED') AND NOT EXISTS(SELECT 1 FROM feedback_copy c WHERE c.feedback_id=f.id AND c.state='POSTED')) THEN RAISE EXCEPTION 'partial delivery has no confirmed appearance'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_agent_job o LEFT JOIN review_job j ON j.id=o.id WHERE NOT EXISTS(SELECT 1 FROM _discarded_job_ids d WHERE d.id=o.id) AND(j.id IS NULL OR j.review_id<>o.id)) THEN RAISE EXCEPTION 'routed job identity changed'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_agent_job o JOIN review_job j ON j.id=o.id WHERE o.status IN('QUEUED','RUNNING') AND(j.status<>'CANCELLED' OR j.processing_status<>'DONE' OR j.cancellation_reason<>'CONTRACT_CHANGED' OR j.worker_id IS NOT NULL)) THEN RAISE EXCEPTION 'old runtime authority survived cutover'; END IF;
 IF EXISTS(SELECT 1 FROM _cutover_old_observation o WHERE o.evidence->'inapplicability' ? 'subject' AND o.evidence->'inapplicability' ? 'prerequisite' AND o.evidence->'inapplicability'->'subject' IS DISTINCT FROM o.evidence->'inapplicability'->'prerequisite') THEN RAISE EXCEPTION 'historical inapplicability keys conflict'; END IF;
 FOR checked_row IN SELECT id FROM result ORDER BY id::text LOOP PERFORM check_result_children(checked_row.id); END LOOP;
 FOR checked_row IN SELECT review_id,practice_id,item_id FROM review_item ORDER BY review_id::text,practice_id,item_id LOOP PERFORM check_review_item_scope(checked_row.review_id,checked_row.practice_id,checked_row.item_id); END LOOP;
END $$;
