 FOR r IN SELECT c.oid::regclass AS name FROM pg_class c WHERE c.relnamespace=pg_my_temp_schema() AND(c.relname LIKE '_cutover_%' OR c.relname IN('_needed_user','_person_map','_new_person','_membership_seed','_job_key_candidates','_job_work','_discarded_job_ids','_work_ref','_item_map','_job_transition','_captured_practice','_capture_decision','_claim_rank')) AND c.relkind IN('r','p') LOOP EXECUTE format('DROP TABLE %s',r.name); END LOOP;
END $$;
